window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_037"]={"n":"郑文焯","dyn":"清","poems":[{"t":"园居早春寄山中客","f":"五言古诗","c":["林鸟春多声，池花落还见。","连情美瞻听，逐物矜芳衍。","盛往识来希，娱新增旧眷。","佳人处帷屏，高制绝雕绚。","碧云殊未期，瑶华独谁荐。","欢怨隔岁年，宿心违缱绻。","载枉《黄鹄》篇，感音发哀断。","夕思初月盈，晨忧繁星散。","良游信乖绝，念子长粲粲。","鸣弹答幽素，撷馨托柔翰。","及时徵昔言，山阿遂嘉践。"]},{"t":"寄幼兰兄潮州","f":"五言古诗","c":["秋馆奄夕阴，近霜桂始华。","晚秀有新妍，胜赏无世哗。","附物徇时美，切情寄幽遐。","渚鸿违北栖，江鱼泳南嘉。","岭表迟高闻，吴趋独哀哇。","苒苒年事别，苕苕旅望赊。","念予同怀暌，兴言行役嗟。"]},{"t":"秋思引","f":"七言古诗","c":["秋风啸谷惊苍松，水帘悬雨千尺淙。","坏衣老僧罢晨梵，空山落叶闻霜钟。","飒然万籁忽岑寂，孤鹤叫破青芙蓉。","山虚水深白云远，嶕峣乱石无人踪。","古来此意谁复会，新声憀亮争蝉蛩。","起拂朱弦三叹息，世无稽蔡吾何从。"]},{"t":"九日泛舟枫桥","f":"七言律诗","c":["云鳞叠空生麴波，酒中倒卧秋山螺。","蛾眉小绿破双萼，醉把茱萸劝残酌。","兰风吹寒歌扇薄，水枕梦回怨萍泊。","吴歈未终枫叶落，二十五声秋点索。"]},{"t":"白雁歌","f":"七言古诗","c":["江城霜信初闻鸿，昨日登高来北风。","菰芦萧萧野水阔，潇湘天尽秋云空。","兰钗小妇夜幽苦，残月楼中弦自语。","盛年孤艳空闭帏，玉颜不及南飞羽。","近闻湖海矰缴多，高飞冥冥愁奈何。","长林乔枝不可择，笑看燕雀纷投罗。"]},{"t":"孛鹿谣","f":"古风","c":["秋孛鹿，损万斛，东畦种禾西畦菽。","禾头生耳菽生蠋，城中穰草千钱束。","孛鹿谣，哀嗷嗷。","昨日湖水平南壕，鹅鸭集庐鱼升桥。","出无航，居无茅，荒荒饥色近在郊。","四乡那不愁漂摇，邻灾况闻江有蛟。"]},{"t":"秋霖行","f":"古风","c":["老农昨入城，为言道光季。","淫雨昼成晦，野湟船入肆。","倾畦连畛水没人，庐游鹅鸭田生鳞。","强梁白梃走檐下，官符到乡还捉民。","吴侬乐岁无余业，年灾一值如赤贫。","公中岂无岁时蓄，南仓北仓雀噪囷。","昨闻诏恤宽租欠，计岁行恩到乡县。","谁怜下户尾毕逋，不输官符输胥掾。","今年秋霖积田水，视昔潦年差尺半。","天时人事不可知，今朝雨雹昨雷电。","我闻此语心忉忉，隐几恍见波澜高。","坐使愁心恋江海，武陵渔者傥可招。"]},{"t":"闻雁","f":"五言律诗","c":["秋水渺无极，愁尽送白云。","西风何太急，北客独先闻。","旅梦苍烟寺，樵歌黄叶坟。","江南鲜矰缴，雨夜尚呼群。"]},{"t":"读高陶堂志微录书后","f":"七言律诗","c":["梦落沧流此辍弦，一官滞调偪残年。","振奇文字投珠晦，垂老功名误瓦全。","宁惜清流论党局，从教才思傲顽仙。","荒荒西曜湛归翼，虚傍柴桑卜墓田。"]},{"t":"旧婉","f":"七言律诗","c":["旧婉前华脉脉思，疏风闲雨阁兰期。","湖山梦冷成诗瘦，弦管声繁易酒悲。","襟上唾花空有恨，尊前梅柳为谁姿。","柔肠苦被明眸割，彻骨风流鬓已丝。"]},{"t":"壬老将去吴感赠长句","f":"七言律诗","c":["霜信初丹晚桂林，闭门秋思已深深。","冥鸿遥带潇湘雨，樊鹤犹余江海心。","云物空濛回北望，诗歌浩荡发南音。","不辞更醉重阳酒，别后兰茳漫独吟。"]},{"t":"元墓山楼重见旧题","f":"七言律诗","c":["空寒烟月五湖湾，经岁看花数往还。","片石谁堪同日语，高云终是在山间。","十年西崦虚仙籍，几度东风破醉颜。","欲采青芝徵旧梦，樵风长识郑家山。"]},{"t":"杨柳 其一","f":"七言绝句","c":["秋尽江干柳未黄，官亭相送只斜阳。","汉南何意先摇落，枉及东风作絮狂。"]},{"t":"杨柳 其二","f":"七言绝句","c":["绿尘帐殿晚阴移，舞袖飘零怨楚姬。","莫把长条赠歧路，故宫犹得妒腰支。"]},{"t":"灵岩","f":"七言绝句","c":["日暮谁闻小海歌，胥屏东望五湖波。","无多故国青山在，枉费宫眉十斛螺。"]},{"t":"夜雨有忆","f":"七言绝句","c":["花外疏疏暗雨过，西园明日绿阴多。","故人不寄潇湘梦，一夜春魂泣女萝。"]},{"t":"齐天乐 登虞山兴福寺楼时癸未始秋","f":"古风","c":["夕阳呼酒登临地。","樽前故人还是。","水国无花，山城自绿，望转征蓬千里。","行歌倦矣。","更一片秋魂，乱云扶起。","醉袖飘萧，海风吹下剑花细。","天涯此楼似寄。","画阑零落处，都为愁倚。","佛鼓荒坛，神鸦废社，今古苍茫烟水。","吴丝漫理。","正波上鸿飞，数峰凄异。","坐尽林阴，甚时重梦至。"]},{"t":"踏莎行 重别次湘和白石道人江上感梦之作","f":"古风","c":["官阁烟寒，客帆风软。","吟边属景愁边见。","归心争共蜀云飞，梦痕总被吴波染。","残酒单衣，残镫泪线。","乱山挂雨尊前远。","江南水阔别离多，断魂分付孤舟管。"]},{"t":"湘月 山塘秋集分题得坏塔","f":"古风","c":["夜铃语断，更斜阳瘦影，谁问今古。","独立苍茫，镇占老，一角青山无主。","衰草丛生，枯枫倒出，时见归禽度。","残烽零劫，仗他半壁支拄。","长见峭倚荒天，凄凉如笔，写愁边风雨。","不许登临，怕倦客、题遍伤心秋句。","卧影空丘，招魂破寺，剩有孤云驻。","梦痕飞上，故王台榭何处。"]},{"t":"八声甘州 西楼九日","f":"古风","c":["唤吟边、瘦月替珠灯，扶魂上西楼。","叹芳时俊侣，尊前掇送，坠梦难收。","又是黄华劝客，须插少年头。","明日尖风阵，绿减汀洲。","笛外乱峰无语，甚秋肠寸裂，还听吹秋。","想湖亭多宴，歌泪迸波流。","自销凝、断襟零佩，剩水云、冷画两三鸥。","休重向，小帘香处，残叶题愁。"]},{"t":"虞美人","f":"古风","c":["断魂空画相思影，细语成悽哽。","鹦哥犹唤旧坊名，几度寻春帘幕误人迎。","年时繫马门前柳，树更如腰瘦。","月胧悬泪夜盈盈，长见小楼圆梦到天明。"]},{"t":"摸鱼儿 金山留云亭饯仲复抚部，酒半闻江上笛声起于乱烟衰柳间，感音而作，不自觉其辞之掩抑也。","f":"古风","c":["渺吴天觅愁无地，江山如此谁醒。","乱云空逐惊涛去，人共一亭幽静。","斜月耿，怕重见，青尊中有沧桑影。","吟魂自警，对潮打孤城，烟生坏塔，笛语夜凄哽。","招提境，还作东门帐饮，中流同是漂梗。","当年击楫英雄老，输与过江鱼艇。","愁暗省，换满目，胡沙蛮气连天迥。","苔茵坐冷，任怪石能言，荒波变酒，莫更赋离景。"]},{"t":"东风第一枝 和梅溪春雪韵","f":"古风","c":["玉斗新梅，珠敲暗竹，江春半酿寒暖。","粉云几处愁深，素波者番恨浅。","寻香旧径，趁细屧、弓痕轻软。","怕笛边、误约飞花，阁住小帘归燕。","沙草际、渐迷望眼，风絮里、暗销醉面。","乍看舞鹤閒庭，又寻印鸿故苑。","吴篷谁倚，画澹远山眉如线。","更镜娥含泪窥人，梦想缟衣重见。"]},{"t":"惜秋华 惠山","f":"古风","c":["软绣山街，翠溶溶，一镜秋妆环照。","向晚画船，相将载愁多少。","夫容不管啼红，暗坠落、烟轻波小。","凄凉，正斜阳送客，湖亭重到。","仙梦绛都杳。","记灯帘俊语，凤鬟香袅。","问紫曲谁解，忆听歌人老。","而今白石清泉，倚玉瓶、乱峰如笑。","幽悄。","误梦寻、燕昏莺晓。"]},{"t":"留春令 中秋夜红楼离席","f":"古风","c":["镜华空满，怨红都在，旧时罗帕。","早是销凝泪无多，怎留向、临歧洒。","枕上阳关催夙驾。","忍今宵歌罢。","从此西楼翠尊空，愿明月、无圆夜。"]},{"t":"点绛唇 西楼感梦","f":"古风","c":["秋馆黄昏，小风香阵欺裙蝶。","近霜花叶。","著意红双叠。","多少新愁，夜夜西楼月。","伤今别。","月圆时节。","长是佳期阙。"]},{"t":"虞美人","f":"古风","c":["镜屏香冷夫容荐。","花趁人凝澹。","问谁下马看梳头。","长是画帘高捲卧清秋。","宿妆留得新眉在。","人意依前改。","一沟脂水绕楼东。","中有几行閒泪往来红。"]},{"t":"瑞龙吟 春怨用清真体","f":"古风","c":["横塘道。","还记碎镜流花，断裙黏草。","多情三百红阑，为谁约住，东风不到。","旷吟眺。","休问玉梅门巷，旧家英妙。","而今著破春衫，唾华泪粉，销凝满抱。","依黯残云心事，过江如梦，清歌催老。","惟有酒边青山，曾见年少。","狂香艳迹，零落兰成槁。","无人听、西园冷咏，南楼清啸。","料理伤春早。","几回付与，燕沉莺悄。","争说还乡好。","离篴怨、归魂将花千绕。","夕阳故国，曲中人杳。"]},{"t":"芳草渡 江南早春重遇中实感梦而作","f":"古风","c":["昨梦里，见别后湘皋，又生兰芷。","正夜窗听雨，镫花报有人至。","怊怅携手地。","销年华多丽。","水驿晚，省是重逢，各自憔悴。","慵倚。","画阑缺处，犹有伤春当日泪。","旷吟望，吴云断草，凄凄恨千里。","乱山侧帽，算楚客，旧狂能理。","展醉眼，一笑尊前老矣。"]},{"t":"一萼红 光绪壬辰人日，用石帚淳熙丙午人日词韵，题其西湖遗象。","f":"古风","c":["石湖阴。","想梅边堕翠，曾上小红簪。","经醉残山，伤春旧月，无奈风过箫沉。","漫回首、垂虹载雪，唤梦醒、空有绕枝禽。","笠泽烟寒，玉峰雪暗，悽绝重临。","宾主百年无几，问浮湘入沔，去住何心。","南渡风流，东州雅旧，遗事休更追寻。","算歌曲、江湖送老，抵当时、锅里几销金。","待访城西马塍，只见花深。"]},{"t":"踏莎行 雨意垂垂春事遒尽红楼曲饯爰托于音","f":"古风","c":["兰气疏襟，竹声凉幕。","卧枝红袅金钗落。","五更残雨酒醒时，罗衾正似人情薄。","帐烛香销，琴尊泪阁。","梦来真悔重逢错。","去年花落旧亭台，西风不减东风恶。"]},{"t":"拜星月慢","f":"古风","c":["虎气高秋，鸱夷遗恨，断送山塘七里。","走马吹花，带歌声流水。","酒醒处，付与、黄昏一片镫火，满地飘零钿翠。","步屧人归，总西风憔悴。","倦追寻，画舸鱼龙队。","中年近，早办登临泪。","不见柳色苏台，换秋烟萧寺。","坠疏钟、月落城乌起。","扁舟夜、暗傍蒹葭舣。","莫更向、碎玉阑干，为伤高独倚。"]},{"t":"玲珑四犯","f":"古风","c":["竹响露寒，花凝云澹，凄凉今夜如此。","五湖人不见，故国空文绮。","歌残明月满地，拍危阑，寸心千里。","一点秋檠，两行新雁，知我倚楼意。","参差玉生凉吹。","想霓裳谱遍，天上清异。","镜波宫殿影，桂老西风里。","携槃夜出长门冷，渐销尽，铜仙铅泪。","愁梦寄。","花阴见、低鬟拜起。"]},{"t":"木兰花慢 八月十八日汎月石湖邻舟感遇","f":"古风","c":["晚凉花积水，送秋老、越来溪。","叹故苑沧波，汎天镜里，曾见鸱夷。","凄凄。","黄昏未了，渐歌阑人似水东西。","自有暗香随袖，残红为惜新题。","文漪。","步绮轻移。","银烛背、翠尊携。","念别后湖山，几回同梦，云散鸿飞。","依依。","兰桡醉解，涴啼痕犹在去年衣。","明月无多圆夜，有情偏向人低。"]},{"t":"湘春夜月","f":"古风","c":["最销魂，画楼西半黄昏。","可奈送了斜阳，新月又当门。","自见海棠初谢，算几番酲醉，立尽花阴。","念隔帘半面，香酬影答，都是离恨。","哀筝自语，残镫在水，轻梦如云。","凤帐笼寒，空夜夜、报君红泪，销黯罗襟。","蓬山咫尺，更为谁、青鸟殷勤。","怕后约，误东风一信，香桃瘦损，还忆而今。"]},{"t":"雨霖铃 甲午人日载雪西崦","f":"古风","c":["江城春霁。","趁东风早，画舸初试。","歌眉镜里仍见，曾携手处，都盈愁思。","梦换繁华旧恨，共明月千里。","但暗忆、红萼莺簪，玉篴吹寒夜重起。","娃乡自古销魂地。","漫倚阑、一霎成憔悴。","年年虎山桥下，花发处、冷香随水。","水纵无情，应带伤春，几点清泪。","算只有、吟袖弓腰，解得流连意。"]},{"t":"玉楼春","f":"七言律诗","c":["春阴多误花时节。","昨夜东风犹有雪。","那知天意著诗情，新见虎山桥上月。","十年旧赏音尘绝。","重赋横枝和泪折。","凄清心事付红箫，暗惜歌前人近别。"]},{"t":"木兰花慢 梁溪晚泊和黄竹斋","f":"古风","c":["问绿汀杜若，谁解为、恨人栽。","叹京袂游尘，吴霜归鬓，客闷难排。","扁舟放愁纵远，好湖山何意乱离来。","斜月还闻邻篴，落花休点吟杯。","水香亭榭忆秦淮。","歌棹晚频催。","念绣额帘花，罗心烛烬，残梦徘徊。","西风谢堂去燕，剩巢痕还占旧楼台。","待把锦书寄与，柔波九曲肠回。"]},{"t":"莺啼序 甲午仲秋薄游江淮瓜步晚渡与子苾舟中连句和梦窗此曲","f":"古风","c":["西阑乍过桂影，倦秋酲闭户。","酒边泪、分付黄花，客燕何意来暮。","棹歌远、吴山自碧，秦云望转淮南树。","怅荒台残柳，春前枉作风絮。","宝扇才疏，画帘十二，换纱烟縠雾。","镜波小、还照离妆，玉容空在纨素。","绣帷寒、愁松雪腕，暗销尽、深盟红缕。","理芳情，搓做柔丝，绾他閒鹭。","桃根旧曲，醉耳重听，过江尚倦旅。","叹十载、杜郎吟赏，又断魂处，翠黯红凄，矮篷眠雨。","二分月色，璚箫吹破，多情赢得天涯老，更渔镫、趁唤瓜州渡。","登临恨晚，荒萤乱点迷楼，照地一片焦土。","春风粉黛，晓日绫纨，剩寸萝片苧。","笑拾得、才人馀唾。","几树官梅，客里狂吟，雪中低舞。","扁舟此去，无情烟水，清歌何处催梦觉，感华年、分算成弦柱。","隋堤鸦散斜阳，故宫庭花，有人唱否。"]},{"t":"莺啼序 登北固楼感事再和文英","f":"古风","c":["西风又闻鹤唳，动秋声在水。","海东日、照满津亭，浪花飞作云蕊。","戍笳引、楼船暝合，荒谯夜火城乌坠。","叹南游孤旅，沧波久断归思。","关塞音书，数驰急羽，感新愁帝子。","笑仙术、空说乘槎，采芝人久未至。","莽中原、貔貅万帐，问何日、龙旗东指。","且衔杯，狂嗅茱萸，醉来何意。","登临罢酒，北顾仓皇，念枕戈不寐。","霜月悄、几回起舞，到此惊见，第一江山，费人清泪。","神京杳杳，非烟非雾，鸡声残梦催哀角，搅回肠、一夜成憔悴。","冥鸿自远，重携倦客扁舟，汎愁镜波天里。","燐燐野烧，逼射甘泉，照万松失翠。","暂小觅、林亭同憩。","侧帽行吟，老柳祠荒，乱鸦飞起。","金焦两点，檐牙浮碧，空梁归尽辽海燕，绕危阑、休向曛黄倚。","伤心大树飘零，更恋遗弓，恨题满纸。"]},{"t":"浣溪纱 秋夜闻隔墙按歌","f":"七言古诗","c":["秋病无名废酒尊。","水西亭榭易黄昏。","独经游地最销魂。","花影自行桥上月，篴声如见曲中人。","燕梁何处起清尘。"]},{"t":"齐天乐 白石、碧山咏物之作，多取是调，托兴深美，因效其体赋蟹","f":"古风","c":["半生谙尽江湖味，西风更无肠断。","蓼溆衰灯，芦滩短舍，夜市秋声零乱。","横行未遍。","叹身世抟沙，蚬螺羞伴。","恨满吴波，喷珠尽作水花散。","彭彭甲兵腹满。","待谁呼郭索，蛮海秋战。","菊訉霜肥，橙香雪老，都付重阳吟盏。","新诗好换。","忆乡味经年，故溪清浅。","月落潮生，一匡愁碧染。"]},{"t":"湘月","f":"古风","c":["桂阴小榭，隔纱栊听水，如坐云雾。","细雨檐花，奈曲里，总是潇潇愁绪。","枫驿初鸿，柳桥残燕，画烛裁秋句。","西阑休倚，数峰相对清苦。","犹忆卧酒琴台，磨空一镜，照青山今古。","塔影苍寒，问石上、招得秋魂来否。","蹋叶虚廊，采香断径，事与孤云去。","凄然良夜，梦游凝想仙侣。"]},{"t":"庆宫春 重登西楼月下闻雁寄怀湘潭王壬老","f":"古风","c":["衰草虫天，断云鱼浪，去帆望转湘碧。","秋影初鸿，江蓠罢采，月明空怨遥夕。","翠疏红冷，记曾占、西楼赋笔。","雕阑仍在，愁倚黄昏，水风残笛。","楚兰一曲伤心，恨魄难招，雾萝烟薜。","江山文藻，登临老泪，故国何堪陈迹。","绮疏芳卷，定寄我、寒梅水驿。","行云歌尽，白眼青天，旧狂谁识。"]},{"t":"望江怨 题北楼春饯图","f":"古风","c":["东风笛，惜别残红旧衫湿。","登高怀故国，画帘飞絮烟江夕。","空尊泣，不见笛中人，断云和梦觅。"]},{"t":"兰陵王 江上逢北使寄书和清真","f":"古风","c":["片帆直，春草连江自碧。","吴亭外飞絮乱鸦，冉冉离天可怜色。","青山恋去国。","应识长安旧客。","归鸿尽，回首暮云，一纸京书泪盈尺。","经年尚萍迹。","叹梦堕吟鞭，香冷歌席。","残花残酒过寒食。","看十里村杏，数行门柳，东风吟恨遍水驿。","甚天限南北。","幽恻。","暗怀积。","念帐镜尘空，廊屧音寂，前游到处成愁极。","但逝水光景，过风箫笛。","沉沉孤馆，更夜尽、断漏滴。"]},{"t":"兰陵王 秋柳和清真","f":"古风","c":["去波直，残柳参差飏碧。","苏台路曾埽坠钿，涴地柔条尽秋色。","依依问水国。","频忆长亭送客。","西风里、携手四桥空，绿平添涨三尺。","春光总陈迹。","记絮袅帘旌，花捲帆席。","汀洲萍实经年食。","嗟两鬓银绾，一声金缕，离魂飞度远近驿。","送秋老江北。","心恻。","乱愁积。","奈舞袖飘零，歌扇沈寂，相思到骨情何极。","念马上残梦，酒边孤笛。","单衣铅泪，似暗雨、夜半滴。"]},{"t":"踏莎行 采莲曲","f":"古风","c":["花券裁红，香筒吹绿。","轻拿踏遍江南曲。","莲心苦里尚回甘，藕丝断后从谁续。","翠帔银泥，钿筐金粟。","牵云曳雪相思属。","弄波莫便采珠还，露房秋泪红盈掬。"]},{"t":"玉梅令","f":"古风","c":["沧波旧苑，又入清风券。","春阴护、傍家池馆。","有药阑几曲，掩袂再来看。","珍丛未谢，梦云已远。","吴缣蜀锦，新诗能换，十年事、暗惊雨散。","问山阳旧侣，到此更谁过，空邻笛、绕花吹遍。"]},{"t":"绮寮怨 宣武城南夜集感事和清真","f":"古风","c":["白眼看天如醉，梦云谁唤醒。","糁绮陌、舞絮狂尘，伤春泪，漫洒新亭。","微茫西山一角，沧波底，日落山更青。","但怪他，片石无言，冤禽恨，抵死填海盈。","旷望去天几程。","珠宫旧事，仙才枉说飞璚，月冷风清，羽衣谱，敛愁听。","苕苕凤楼残点，独立尽，五更情。","漂花满城。","东风不到处，花又零。"]},{"t":"还京乐","f":"古风","c":["放愁地，说与沧江旧曲谁重理。","纵翠纱笼句，白雪笑我，仙才空费。","又故山归后，残春事与浮名委。","镇断送明日，陌上看花閒泪。","向清波底。","见文章、流锦名花，诉尽东风，零落旧味。","堪嗟冶叶倡条，傍凡门、艳数桃李。","恨迢迢，拌玉剑埋云，金刀断水。","料得西楼月，窥人还自憔悴。"]},{"t":"夜飞鹊 出南郭望西山和清真别情","f":"古风","c":["城南有情月，知我悽其，临别更送清辉。","吟边白发已愁尽，京尘依旧缁衣。","烟霄旷回眺，看仙山楼阁，海戍旌旗。","长安梦短，过津亭、酒醒偏迟。","身似十年江燕，帘幕易秋风，残社空归。","休问乌衣故国，寻常陌巷，重到应迷。","数峰缺处，倩苍云、补向天齐。","但红桑成亩，青芜变海，弱水还西。"]},{"t":"蓦山溪","f":"古风","c":["吟边灯火，梦熟城南路。","归骑每侵晨，月初沈，西山缺处。","残笺满袖，都是别君词，空愁语，休延伫，酒醒天涯去。","飘零到此，客枕高楼雨。","鹤唳似惊风，渺瓯蛮，瘴江战鼓。","扁舟不繫，一夜故园心，杯未举，愁先注，白发缘行缕。"]},{"t":"月下笛 戊戌八月十三日宿王禦史宅，夜雨闻邻笛感音而作和石帚。","f":"古风","c":["月满层城，秋声变了，乱山飞雨。","哀鸿怨语。","自书空、背人去。","危阑不为伤高倚，但肠断、衰杨几缕。","怪玉梯雾冷，瑶台霜悄，错认仙路。","延伫，销魂处。","早漏泄幽盟，隔帘鹦鹉。","残花过影，镜中情事如许。","西风一夜惊庭绿，问天上，人间见否？","漏谯断，又梦闻孤管，暗向谁度。"]},{"t":"莺啼序 秋感和梦窗丰乐楼韵","f":"古风","c":["沧洲半残画槁，认河山错绮。","自槎客、艳说仙瀛，浪叠愁满空际。","蜃嘘起，楼台幻境，金银夜气浑无霁。","怪尘昏，蛮海惊鸢，跕影都坠。","陈迹苍黄，对酒看剑，向青天漫倚。","汉宫月、犹过边亭，堕榆飞尽寒翠。","最销凝、昆池劫墨，石鳞泣、秋棱荒水。","阅年涯，三浅蓬莱，此身何世。","长安似弈，局外樵柯，睡境正深美。","幽恨切，数声啼鸟，梦里谁见，覆雨翻云，楚天疑事。","西山缥缈，香霏一片，玉龙哀变清商曲，漏沈沈、烛背帘垂地。","抛残旧舞，霓裳独坐繁霜，泪花湿红嫠纬。","宫槐翳日，苑柳扃烟，念凤楼久迟。","但梦绕、瑶池仙步，鹤怨猿猜，望断层城，玉梯十二。","骄云满眼，森森冠佩，江关投老词赋客，叹京尘空染忧时袂。","伤心孤燕巢林，乱叶迷归，夕阳故里。"]},{"t":"秋思耗 半雨楼闻雁和梦窗","f":"古风","c":["衰帽西风侧，骤雁声催送，暮城寒色。","灯院雨昏，晚花中酒，愁浸肠窄。","倚歌扇高楼，四弦和泪诉掩抑。","见数峰、江上碧。","想故国云横，几行归尽，又作早秋南旅，有情堪忆。","残夕。","檐铃断滴。","唤素娥、澹洗铅饰。","怕闻邻笛。","明朝窥镜，鬓华暗白。","误旧约、青鸾信乖，春梦如过翼。","念远客、应惯识。","漫岁餐稀逢，重门无字寄得。","恨隔霜榆塞北。"]},{"t":"忆旧游 乙亥五日，浮家西崦，信宿石壁精舍，见湖壖渔家垂灯叠鼓，饶有节物，感时赋此。","f":"古风","c":["正梅风转溽，麦浪吹凉，晴泛吴桡。","未了寻幽兴，赋枇杷晚翠，一掬金抛。","五湖料理三亩，多事误青袍。","怅听水灯前，看山枕底，梦境苕苕。","萧条，旧兰若，问烟雨楼台，谁换南朝。","剩有苍黄壁，压颇黎万顷，断劫难销。","凄其五日情事，残醉虎山桥。","叹满地沧波，渔舟夜笛何处招。"]},{"t":"浣溪沙 从石楼石壁往来邓尉山中","f":"七言古诗","c":["一半梅黄杂雨晴，虚岚浮翠带湖明，閒云高鸟共身轻。","山果打头休论价，野花盈手不知名，烟峦直是画中行。"]},{"t":"庆春宫 桥西新营后溪植援杂花幽树，经秋成阴，时有冷客登楼醵饮，萧然托寄，辄付伧歌。","f":"古风","c":["窗岫遥青，帘波空翠，卧临画里江城。","斜月琴床，低花衣桁，枕溪疏绮多明。","几枝霜橹，暮寒迸西楼雁声。","小阑红袖，倚遍珍丛，玉笛谁横。","歌尘一片凄清，别岸垂杨，曾见藏莺。","屏烛秋啼，镜花春影，赋愁空费閒情。","旧游吟境，梦云隔蓬莱几程。","仙才自惜，莫枉山中，猿鹤知名。"]},{"t":"满庭芳 西馆新阴，花枝可撷，匆匆不知春过半已。","f":"古风","c":["行锦花阴，隔纱春语，好风香出梅梢。","翠尘帘捲，新树过人高。","休惜年芳晼晚，沧洲梦轻付吴桡。","低回处，江南旧燕，零落谢堂巢。","东风，还似客，梨云粉冷，蕙雪红销。","近清明歌酒，愁欠谁浇。","一卧西楼听雨，閒情倦，别枕笙箫。","前游续，山塘载月，斟酌过横桥。"]},{"t":"满庭芳 江山饯春","f":"古风","c":["南雪兰襟，东风茸帽，旧情人比花狂。","江城画里，楼阁隐垂杨。","可奈春霏冉冉，都换了新绿池塘。","销魂地，残红有恨，还作燕泥香。","年年，春尽日，疏灯听雨，总是他乡。","纵清歌缓客，怕近离觞。","早识芳心一点，收拾与，蝶粉蜂黄。","今宵梦，吴波半剪，应附北归航。"]},{"t":"沁园春 虎山桥重泊秋晚登眺","f":"古风","c":["衰柳西湾，冷枫南坞，秋横野航。","见秦眉天镜，乍惊离合，越鬟水枕，能令低昂。","残霸空丘，故宫成沼，赢得渔樵买醉场。","清尊对，剩一螺顽碧，虎老山荒。","苍凉重舣鸥乡，渐红叶，吹寒零雁行。","记五湖雪棹，探梅诗瘦，两崦霜笼，报橘书香。","寸岫仙云，尺波尘海，一笑登高理旧狂。","移家好，信石芝堪采，剩赋沧浪。"]},{"t":"龙山会 虎丘作重九，时自光福里回舟，和君特载酒双清之作。","f":"古风","c":["塔影窥林罅，落雁汀烟，画舻霜花亚。","虎山桥上月，移梦近、还过云泉亭下。","衰帽侧高秋，堕巾趁、山容淡冶。","最销凝，吴篷暮雨，歌前暗洒。","因忆旧节题香，踏醉花街，倚少年骄马。","勌游狂态尽，珠箔坠、独自飘灯残夜。","人事水东西，凭高泪、流红迸泻。","漫归吟，冷枫剩有一瓢诗挂。"]},{"t":"虞美人 题红桥归骑画扇","f":"古风","c":["澹烟洗得春山瘦。","眉妩从谁斗。","横桥西畔小桃枝。","一自插花人去怨开迟。","马蹄芳草经游地。","重到销魂易。","红楼长占柳阴阴。","只是柳条不繫少年心。"]},{"t":"贺新郎 秋恨","f":"古风","c":["暗雨凄邻笛。","感秋魂，吟边憔悴，过江词客。","非雾非烟神州渺，愁入一天冤碧。","梦不到、青芜旧国。","休洒西风新亭泪，障狂澜、犹有东南壁。","空掩袂，望云北。","雕栏玉砌都陈迹。","黯重扃、夷歌野哭，晦冥朝夕。","十万横磨今安在？","赢得胡尘千尺。","问天地、榛荆谁辟？","夜半有人持山去，蓦崩舟、坠壑蛟龙泣。","还念此，断肠直。","日落羌笳咽。","认一行、高鸿尽处，五云城阙。","满眼惊尘还乡梦，重见昆池灰劫。","更马上、琵琶催发。","露冷横门移盘去，甚金仙，也怨关山别。","愁寄与，汉家月。","故人抗议多风烈。","漫消魂、题诗陇树，谁旌奇节。","易水空成填恨海，西北终忧天缺。","但目尽、平烟区脱。","不信天心浑如醉，好江山、换了啼鹃血。","长剑倚，向谁说。"]},{"t":"菩萨蛮 望月有怀","f":"古风","c":["桂宫寂寞花前后，天阶玉露金风骤。","云外小骖鸾，也愁高处寒。","夜明秋半镜，暗缺山河影。","灯火梦长安，觉来西笑难。"]},{"t":"汉宫春 庚子闰中秋","f":"古风","c":["明月谁家，甚今年今夕，多事重圆。","移盘夜辞汉阙，贮泪铜仙。","珠帘画栋，倒寒波、空影如烟。","魂断处，长门烛暗，数声惊雁蛮弦。","还见山河残影，恁磨成桂斧，补恨无天。","凄凉镜尘顿掩，云里婵娟。","东华故事，祝团圞，归梦空悬。","凝望久，蓬壸翠水，西流好送槎还。"]},{"t":"玉楼春 城西楼晚眺","f":"七言律诗","c":["惊烟连海掀风色，辽雁秋稀音信隔。","王孙芳草不成归，绿遍天涯无路陌。","悬悬愁眼迷云北，到处登临怀故国。","夕阳楼上好青山，只是黄昏留不得。"]},{"t":"雨霖铃 恨别和柳屯田","f":"古风","c":["并刀难切，是离肠恨，梦雨都歇。","繁华似水流去，回首处，车尘临发。","冷落关河送远，有孤雁悽噎。","念旧苑、衰柳寒烟，玉笛吹愁满空阔。","铜驼陌上伤今别，更断魂客里催佳节。","黄昏满地花影，依约见，故国秋月。","万里清霜，休问香篝翠被谁设。","却怨入帘底西风，付与残蛩说。"]},{"t":"摸鱼儿 沪江送春词","f":"古风","c":["更尊前、几回西笑，茫茫时事如许。","长安一雨分新旧，惟有夕阳无主。","春思苦，怕花满，红桑无地悲离黍。","春归甚处，但残燕空林，乱莺芳草，总是断魂路。","嗟迟暮，休倚兰成词赋，江关赢得孤旅。","高楼纵续笙歌梦，愁带北来笳鼓。","乡信阻，想寂寞，珠帘尚捲西山雨。","凄弦自语，恁冷泪成波，荒波变酒，浇遍赵州土。"]},{"t":"燕山亭 题自画蓟门秋柳图","f":"古风","c":["衰柳空城，羌笛数声，湿了楼台烟雨。","珠箔四垂，客燕迷归，栖老绿阴无主。","弱不禁攀，更愁唱、阳关西去。","凝伫。","剩旧宛歌尘，暗飘金缕。","还记骄马章台，正花拂长堤，麦波随步。","而今莫问，解舞腰肢，凄凉故宫谁妒。","便唤春回，忍再见，倚帘吹絮。","歧路，肠断也，一丝丝苦。"]},{"t":"禦街行 红桥饮席感少年事","f":"古风","c":["峭寒剪剪风如水，又乱飐、花阴碎。","月明桥上玉阑干，曾见凭春罗袂。","好天凉月，依然昨夜，只是人憔悴。","当时何限风流地，尽赚得、销魂计。","年来对酒怕闻歌，换了疏狂身世。","分明襟上，唾花醉粉，都作今朝泪。"]},{"t":"过秦楼 后溪连雨新渌平桥一楼卧临城西陂船舫皆从几案间过晚霁见月水光花影澹然空寒有怀丁酉秋石壁山望湖台夜游流连光景动踰岁时属景不自知其词之凄异也","f":"古风","c":["过雨檐花，透风窗竹，露点翠梧金井。","林梢小阁，曲枕溪流，静绿荡胸千顷。","帘捲夜近，银河秋浸天阶，水明星静。","欠追凉绮袖，一枝横玉，满身云影。","回忆处、月气湖烟，空台摇落，上下卧临清镜。","淩波弱步，湿雾香鬟，梦断数峰青回。","年事如今暗惊，燕草天荒，吴枫江冷。","但孤云远水，愁入离痕泪枕。"]},{"t":"玉楼春","f":"七言律诗","c":["春风秋月资游计，独我尊前长费泪。","几生心苦到词人，风月只供惆怅地。","繁华故国今何世，满目山河成古事。","小楼孤烛梦回时，著枕愁来无处避。"]},{"t":"浪淘沙慢","f":"古风","c":["坠月悄，花光练结，梦绕西碛。","倒影浮杯尽绿，吹香点袖自碧。","想载雪横江浇大白。","正暝蹋、一叶苍茫，又数峰青入短篷笛，烟水弄愁色。","脉脉，旅怀仗酒能释，叹游旧零落如花雨。","孤绝寻芳客。","认石屏苔屐，依稀陈迹。","眼前好景，空绕枝、百转愁肠都窄。","年事换伤春残槁，西园约、梦境顿隔。","翠禽啼、繁英满路陌。","似泪粉、乱点东风，怅恨极，清歌更有何人拍？"]},{"t":"玉烛新 小春海棠，梦窗词手稿有是题，丁香结一解，江南冬燠，春卉再荂而海棠益凄丽可玩，因依梦窗题格赋之。","f":"古风","c":["冰绡和泪浣。","又梦唤春回，绕花千转。","凤窠织就同心锦，肯为伤秋肠断。","娇霞半面。","趁醉夜、珠帘重捲。","催冷艳，还照珍丛，愁凝蜡盘红短。","依依睡起西阑，怪海国狂尘，旧芳都换。","倚寒翠袖应自惜，镜里过时匀染。","移春小槛。","问月地、云阶谁见。","休再觅、颠嫁东风，妆成恨晚。"]},{"t":"法曲献仙音 灵岩览古次韵梦窗","f":"古风","c":["妆濯池花，步鸣廊叶，晚色苍凉僧院。","乱石牛羊，古台麋鹿，江枫黯愁霜点。","近水市菱歌起，吴声镇哀怨。","旷怀远，问鸱夷、载春何处，怊怅地、一径旧香恨染。","箭引越来溪，射晴波、秋练如剪。","废柳残蝉。","替宫魂、歌舞肠断，算繁华成沼，故国青山还见。"]},{"t":"八声甘州","f":"古风","c":["荡岩霏、弄晚点荒寒，渔灯两三星。","叹风流残霸，湖山灵气，空葬倾城。","一镜吴波变沼，花雨洗蛮腥。","片石兴亡恨，玉轸无声。","惟有西江明月，照故宫残梦，梧叶催醒。","奈登临愁眼，还向此山青。","更谁吹、乌栖哀调，唤暮鸿、烟际落芦汀。","馀情寄，白云题句，连步天平。"]},{"t":"湘月 天平山上白云亭酌泉晚眺，欲寻远公石屋不果，归路看红叶泊鹭飞浜作。","f":"古风","c":["乱峰唤客，引幽筇藓步，飞上空翠。","旧赏林亭，更暝蹋，到地秋声红碎。","裂壁通樵，崩厓辟鸟，风谷铿环佩。","斜阳屏画，舞枫欲共天醉。","别有石灶松烟，半坳云乳，泻连筒珠缀。","滴尽吴根，怕化作、一匊沧波残泪。","岩迹台荒，湖光镜冷，秋思生高袂。","灵扃何许，雨花夹磴飘坠。"]},{"t":"天香","f":"古风","c":["薰亚金丝，香参玉垄，沈沈冷麝如水。","故国茄花，王孙芳草，尽化海山云气。","半囊晻蔼，空悟破，枯禅一指。","休问壸天日月，销磨苾刍身世。","拈来信多妙谛，贮烟煴、写经馀事。","叹息百年硕果，等閒匏系。","万感都成蜡味。","但愁惹西来暗尘起。","更倦残熏，生酸老泪。"]},{"t":"兰陵王","f":"古风","c":["断肠直，春梦池塘自碧。","吴笺恨零落旧题，别后湖山总无色。","凄凉恋去国。","同识蜉蝣过客。","低徊处，春树暮云，江鲤沈沈素书尺。","南游共萍迹。","记载雪连桡，吟月移席。","一官直等嗟来食。","愁万里蓬转，十年匏繫，长安漂泊似传驿。","但魂绕关北。","哀恻。","岁时积。","叹蜀锦江空，秦镜尘寂，瑶华玉匣伤心极。","怕腹痛回轸，感音邻笛。","招魂何处，泪万点、当酒滴。"]},{"t":"念奴娇 甲辰仲夏，半塘老人过江访旧，重会吴皋，感遇成歌，以致言叹不足之意。","f":"古风","c":["小山丛桂，问淹留，何意空歌招隐。","自见淮南，佳客散，鸡犬都沾仙分。","碧海三尘，白云孤抱，不羡灵飞景。","仙才谁惜，世閒空舐丹鼎。","我亦大鹤天边，数峰危啸，一觉松风枕。","三十六鸥盟未远，独立沧江秋影。","词赋哀时，湖山送老，吟望吴枫冷。","梅根重醉，旧狂清事能领。"]},{"t":"鹧鸪天 胥口是范蠡从入五湖处，秋夕览古有怀。","f":"古风","c":["云物凄清秋满湖，遗愁梦落故宫梧。","西江终古无情碧，送了鸱夷便沼吴。","烟草迥，水禽呼。","越溪寒雨战菰蒲。","扁舟赚得西施去，枉费良金写作图。"]},{"t":"高阳台","f":"古风","c":["灯市星阑，桥浜雪老，伤春倦赋登临。","旧燕重逢，十年犹自巢林。","渡江柳眼青如许，见故人、江上愁心。","感前尘，珠箔寒飘，镜缕颓侵。","东风又绿离忧草，记捐芳楚佩，题泪吴襟。","梦冷铜驼，可怜人事俱沉。","五湖未了扁舟兴，怕乱愁、还比花深。","掩园扉，行药归来，一枕春阴。"]},{"t":"鹧鸪天","f":"古风","c":["细语檐禽破晓霏，竹声凉翠梦先知。","酒醒一枕红兰泪，染取蛮笺剩写诗。","幽事浅，世情稀。","閒花飞尽见高枝。","一春雨横风狂过，绿遍池塘无是非。"]},{"t":"清平乐","f":"古风","c":["旧寒如水，波织帘花碎。","小雨樱桃红涨地，犹是去年天气。","贪眠笑比吴蚕，东风醒醉长兼，判却一春怊怅，为谁肠断江南。"]},{"t":"二郎神 和湘绮翁西安北苑题壁","f":"古风","c":["夕阳旧苑，又过客、曼歌离黍。","想云近仙居，香昏龙气，空锁千门榜署。","漫说长安，堪西笑尽，梦逐京尘飞去。","嗟殿柳、燕归宫槐，蝉断暗闻铃语。","前度。","画轮移雉，玉阶班鹭。","看地转天回，终南古黛，不减西山翠妩。","汉月悬秋，秦云媚晚，销得楚狂题句。","但暗忆、彩笔曾干，气象白头非故。"]},{"t":"一萼红 春馀夏始，园卉向残，檐果垂熟，绿阴如梦，旧雨不来，即事和白石此解以寓兴。","f":"古风","c":["晚帘阴。","又韶红换景，兰药已抽簪。","芳援疏篱，珍丛叠架，天似残醉沈沈。","乍过雨、樱桃烂熟，款好语、檐际下幽禽。","旧赏林亭，俊游群屐，呼酒谁临。","还念庾郎憔悴，托临江故宅，倦赋愁心。","蓱迹鸥轻，松巢鹤老，尘外吟境堪寻。","待新句、琅玕遍刻，有清籁、相和冷敲金。","写入溪山画图，闭户云深。"]},{"t":"满江红","f":"古风","c":["竹隔桥南，有竹里、人家小葺。","依约似，浣花门径，数椽幽僻。","居近梅家西市隐，补吟桂树东城植。","念岁寒，何意老江村，今非昔。","怀旧隐，三高宅，空遐慕，五噫客。","叹百年，枯菀一般陈迹。","归燕犹寻斜日垒，閒鸥且占沧波席。","待到门，春涨棹歌来，渔榔集。"]},{"t":"法曲献仙音 园居春尽病起闻雨述怀","f":"古风","c":["诗骨裁花，酒香行药，径曲苍苔埋步。","暗烛吹烟，冷篝销雪，愔愔晚寒帘户。","甚梦也和天瘦，空阶夜还雨。","悄吟绪，占吴根、小城一角，墙柳外、依约远山黛妩。","絮捲陌尘飞，放东风、莺燕无主。","故国楼台。","映沧波、空剩歌舞，怕雕阑都换，更倚伤春高处。"]},{"t":"鹧鸪天","f":"古风","c":["水竹依稀濠上园，苍烟五亩绝尘喧。","半床落叶书连屋，一雨飘花船到门。","寒事早，恋清尊。","狸奴长伴夜毡温。","老来睡味甜于蜜，烂嚼梅花是梦痕。"]},{"t":"西子妆慢","f":"古风","c":["山送月来，水漂花出，一片吴墟焦土。","坡陀衰草下牛羊，镇苍凉、废谯沈鼓。","青芜漫赋。","叹残霸、都倾一顾。","话遗尘、有故宫归燕，伤心高处。","登临阻。","玉槛瑶梯，梦断香屧步。","只馀秋色过墙来，做愁颦、岫眉当户。","霜笳暗度。","恁吹彻、觚棱无主。","剩荒丘，夜夜啼乌更苦。"]},{"t":"锦帆泾","f":"古风","c":["一濠剩绿，有当年、西子淩波尘影。","分得香溪三尺玉，曾试春风宫锦。","仙步翩鸿，艳歌浮鹢，转烛空明镜。","漂花暮水，绕城犹作荒哽。","休问金姆桥边，沧波故苑，游鹿苔蹊冷。","越网千丝肠共断，输与菱娃烟艇。","疏蓼栖。","霜，衰荷战雨，门外秋光迥。","渔矶分席，隔篱时唤清饮。"]},{"t":"小重山令","f":"古风","c":["一雨添花作地衣，伤春春不见，梦依稀。","吴蚕犹续去年丝，相思老，休织断肠词。","酒醒昔游非，西园题恨处，几斜晖。","扁舟心事白鸥知，清风过，长扫竹间扉。"]},{"t":"惜红衣 中秋夜，彊村翁蹋月见过，秋花宛娈，襟韵清浃，因和白石自制无射宫一曲兼寄伯宛舍人沪上。","f":"古风","c":["醉枕销凉，吟笺度日，枉抛心力。","洒袂清风，苔扉款深碧。","凉蟾似水，还解伴、江城秋客。","沈寂，留坐桂丛，忆年时游息。","萧条巷陌，踏叶回廊，题愁乱红藉。","相思梦老海国，望云北。","料得旧盟鸥鹭，省惯倦游来历。","奈后逢良夜，空照屋梁颜色。"]},{"t":"惜红衣","f":"古风","c":["别梦催秋，游情展日，倦吟馀力。","听雨残尊，檐花汎湘碧。","书期间阻，空伫想、淞滨幽客。","音寂，江燕晚栖，觅巢林休息。","京尘故陌，满眼骄云，诗狂久声藉。","飘零恨似去国，旷南北。","可忆乱离山水，老境不堪重历。","算压装缃素，添作一江行色。"]},{"t":"惜红衣","f":"古风","c":["玩月来时，乘涛去日，试帆风力。","倦卧沧江，淞波剪愁碧。","吴缣换句，频寄慰、东园书客。","萧寂，吟伴岁寒，却移枝栖息。","花蹊柳陌，旧赏亭池，苔茵翠堪藉。","佳邻买断水国，小桥北。","漫说五湖三亩，林下几人身历。","趁冷枫题醉，不羡隔墙春色。"]},{"t":"惜红衣 岁晚有怀继歌以写","f":"古风","c":["旧思停云，高歌送日，感秋颓力。","隔雨江楼，冥鸿怨遥碧。","兰茳泪把，凭寄赠、长安游客。","凄寂，诗梦倦寻，说风流都息。","铜驼广陌，粉醉金迷，狂尘总陵藉。","羁吟眷念上国，海山北。","耐得一丘吾老，不数十洲飏历。","但岁寒尊俎，谁赏菊丛佳色。"]},{"t":"惜红衣 泾上幽居，览古悲秋，有江山摇落之感，叠用旧韵寄慨于言。","f":"古风","c":["侧帽高秋，题襟胜日，旧狂才力。","倦赋登楼，松关卧荒碧。","江空岁晚，天付与、樵风园客。","清寂，沧海梦还，觉龙吟波息。","珠尘绮陌，栖老年芳，如今草堪藉。","高楼望断旧国，渺西北。","依约废陂衰柳，犹识越兵来历。","对小城烟树，红入夕阳无色。"]},{"t":"惜红衣","f":"古风","c":["断阕吟秋，连筒计日，费人歌力。","怨叠清商，衰兰荐寒碧。","旗亭旧价，空送老、江南词客。","幽寂，云水唱酬，托微波通息。","苔钱万陌，买尽閒愁，伤秋鬓蓬藉。","青芜梦绕旧国，雁行北。","漫忆十年尘事，沧海几回亲历。","赋桂丛招隐，分半石芝山色。"]},{"t":"蓦山溪","f":"古风","c":["故家乔木，门巷桥通市。","市隐有林峦，记听秋，冷枫疏绮。","定巢新燕，胥宇报先声，轻梦占，旧楼台，解道迁莺喜。","红梅一曲，词客风流地。","霜叶胜花妍，算吴歌，好音能继。","渔樵争席，输与海鸥閒，秋色里，许平分，早办为邻计。"]},{"t":"踏莎行 丁未秋夕，石湖醉泊，登千岩观玩月，有忆昔年连棹之游","f":"古风","c":["桂影筛金，竹声碎玉。","西风凉到文波縠。","镜花曾见夜妆红，岩霏不上秋眉绿。","踏月溪桥，题云礀屋。","伤心易触登临目。","清歌如水梦如尘，旧游肠断无因续。"]},{"t":"临江仙 浔阳岁除","f":"古风","c":["岁岁无聊当此夕，那堪听雪关津。","一杯蓝尾怕沾唇，离声残雨夜，归思乱山春。","帝里风光饶节物，老来梦迹都陈。","梅花应笑渡江人，寒烧官烛短，愁试客衣新。"]},{"t":"烛影摇红 江雪残春，试灯初夜，有忆吴市旧游，和梦窗元夕微雨韵寄伯韬、彊村苏州。","f":"古风","c":["雪黯江城，满湖岚气春寒浅。","上灯楼阁晚晴初，箫鼓谁家院。","蜜苣围香正暖，夜蛾愁，行云蘸遍。","旧情无奈，踏月歌沈，淩波尘溅。","转烛年端，雨声空切吴娘怨。","小梅落靥又东风，偏趁天涯看。","忆别皋桥酒散，寄横枝，江南梦远。","暗闻笛语，早晚归舟，花香篷捲。"]},{"t":"水龙吟 皋桥水楼曲宴醉别瞻园，会馀岁暮有九江之役，载雪过白门，愿言不从，赋此感叹。","f":"古风","c":["出门一笑横江，酒醒重问皋桥旅。","残釭厌梦，离杯衔泪，伤春歧路。","三十年前，相逢同是，承平俊侣。","换沧波身世，云愁海思，算萍梗知人苦。","不信兰成老去，赚狂名、萧条词赋。","江山如此，文章何用，英雄无主。","独立苍茫，楼船西下，清淮东注。","欠胡床，为弄梅花，笛里唤青溪步。"]},{"t":"瑞龙吟 听枫园饯春席上和清真","f":"古风","c":["寻诗路，还记小市苍烟，旧家红树。","依稀残月残花，丽情俊赏，销凝是处。","旷吟伫，犹有定巢新燕，占春帘户。","留连晚色年芳，画屏翠烬，馀香共语。","前度京尘游袂，酒边联唱，花间愁舞。","重见断魂天涯，人换新故。","江郎恨笔，休倚伤春句。","飘零又、南楼罢饮，西园归步，世事浮云去。","老怀到此，茫茫万绪。","不绝情如缕。","和泪挽、东风哀弦连雨，梦歌怨叠，一江萍絮。"]},{"t":"瑞龙吟 袌碧先生和清真是阙见示，怀古伤春，高健处不减耆卿风格，继声报之。","f":"古风","c":["西桥路，还认故苑飘花，小城攲树，悽悽江国年芳，怨红泪粉，魂销甚处。","悄延伫，休念旧狂清事，镂香题户。","悲来一曲回风，满汀堕蕙，零弦自语。","空度春光流景，引杯看剑，愁多慵舞。","肠断庾郎哀吟，知为谁故。","推烟唾月，何用惊人句。","伤心见、新亭老泪，临江遗步，转烛繁华去。","酒醒自理，悲欢坠绪。","年鬓催霜缕。","归梦绕、沈沈荒台云雨，楚天恨隔，夕阳飞絮。"]},{"t":"霜花腴 怀梦窗杨柳阊门故居即用其自度曲韵","f":"古风","c":["过江旧客，怅倦游、浮生误了儒冠。","西馆花飞，南桥萍老，吴城久住偏难。","水天梦宽。","奈燕归、飘泊依前。","叹巢痕、阅尽东风，夕阳乔木想高寒。","京国旧居如驿，又金阊柳色，几换吟蝉。","华屋空丘，神州沈陆，苕苕此恨谁笺。","夜钟到船。","认故山、愁黛连娟。","感年芳、送老秋词，断云和梦看。"]},{"t":"一萼红 园夏即赏","f":"古风","c":["半阴晴。","殢云容雨意，梅熟又江城。","帘桁凝烟，庭除泼水，空想歌扇花萦。","渐衣润、添香满鸭，费熨帖、春恨总难平。","斗草人归，采兰天近，谁唤愁醒。","依约一年芳事，奈新期旧赏，节物堪惊。","寻梦蕉迷，追凉竹醉，閒书长解尘缨。","看高柳、池塘自碧，怕重见、江燕共秋零。","最忆清风故人，一枕诗声。"]},{"t":"声声慢 臞庵抚部晚秋宴席","f":"古风","c":["庭柯疏桂，井干寒梧，萧森幕府清秋。","楚佩兰情相将，珠履风流。","戟门夜澄如水，咏凝香，传遍吴讴。","追雅宴，胜云开，东阁月满南楼。","回忆霜台旧柏，映花明，旌节江国鸣驺。","白发丹心，吟湘梦绕神州。","一池晚莲红汎，点馀波、容有閒鸥。","延胜赏，好湖山、尊俎借筹。"]},{"t":"声声慢 秋雨酬瞻园同年","f":"古风","c":["荒苔綦迹，落叶诗声，孤檠听雨江关。","寂寞鱼龙沧波，独放鸥閒。","西风庾愁催赋，剩空园，栖老霜菅。","念游旧，有词坛，白雪幕府青山。","楚客悲秋何限，只斑斑，竹泪迸付蕉弹。","铜狄摩挲，曾歌汉月移盘。","南云梦华重聚，荐吴尊、休汎衰兰。","旷吟望，镇哀时、相共岁寒。"]},{"t":"声声慢 秋晚索居简彊村，有怀京国旧游。","f":"古风","c":["檐花残雨，廊叶新霜，愁闻秋尽啼蛩。","水石高閒琴尊，岁晚稀逢。","隔江乱云催暝，卧空山，独对寒松。","倦游感，话辽天，归鹤湘浦来鸿。","一梦惊尘汉阙，记金坡，剑履折槛家风。","清浅蓬莱，仙槎换了渔篷。","栖栖五湖心事，放虚舟、伴老云东。","正凄悄，见斜阳、天外数峰。"]},{"t":"高阳台 园夜寒尊与彊老清话待月，溪堂有烟水苍茫之感，明日赋此索和。","f":"古风","c":["连榻听松，过门看竹，相期放迹林峦。","一卧沧江，秋光几换颓颜。","凄凄夜雨黄花泪，更为谁、弹满西阑。","恁销沈，玉海珊枝，不挂渔竿。","曾传交让池边树，有吴侨并宅，偕隐高閒。","片席鸥波，应通鹤梦清寒。","归云已是忘机地，漫醉抛、屋里青山。","最知心，斜月窥尊，长送君还。"]},{"t":"满庭芳 新治西寮，岁晚叙意，辄题一解，时戊申十月。","f":"古风","c":["邻寺霜钟，故城烟柳，旷如家住江村。","半溪黄叶，老树自知门。","胥宇还来旧燕，花落后为补巢痕。","閒情有，白鸥留客，呼取隔篱尊。","楼台，谁是主，梦中槐蚁，总付秋魂。","算扁舟身世，犹繫吴根。","向晚青山更好，人外想，林屋风存。","生涯托，幽居水竹，渔钓长儿孙。"]},{"t":"月下笛 寒夜闻床下蟋蟀感矣。","f":"古风","c":["落叶閒阶，秋声徇了，为谁吟苦。","霜蟾挂户。","漏签迟、带愁度。","王孙已是无魂断，更何意、凄凉自语。","正机丝泪织，辘轳肠转，耿耿残曙。","凝伫，寻秋处。","记斗草金笼，旧家儿女。","閒情换日，岁寒时事如许。","虫天万感沈沈夜，忍重听、空帘暗雨。","漫怊怅，说与灯前事，梦也无据。"]},{"t":"迷神引","f":"古风","c":["看月开帘惊飞雨，万叶战秋红苦。","霜飙雁落，绕沧波路。","一声声，催笳管，替人语。","银烛金炉夜，梦何处？","到此无聊地，旅魂阻。","眷想神京，缥缈非烟雾。","对旧河山，新歌舞。","好天良夕，怪轻换华年柱。","塞庭寒，江关暗，断钟鼓。","寂寞衰灯侧，空泪注。","苕苕云端隔，寄愁去。"]},{"t":"安公子","f":"古风","c":["急雨惊鸣瓦，转檐风叶粉如洒。","闭户青山飞不去，对沧洲屏画。","换眼底衰红败翠供愁写。","窥冷檠半落吟边灺。","正酒醒无寐，怊怅京书题罢。","到此沈沈夜，为谁清泪如铅泻？","梦想铜驼歌哭地，送西园车马。","叹去后阑干一霎花开谢，空怨啼望帝春魂化。","算岁寒南鹤，解道尧年旧话。"]},{"t":"木兰花慢 己酉闰春，园梅盛开，时彊村翁以特徵不起，高卧空斋，因置酒招之，极意吟赏，有林下相从之乐，赋以见志。","f":"古风","c":["闭门春不管，又何处放春来。","自卧雪西园，垂垂江树，空老莓苔。","徘徊冷香水驿，甚长安、花事等閒催。","欲把一枝寄与，好风吹向谁开。","安排涧曲林隈。","寻蜡屐、荐吟杯。","叹旧家红萼，几番羌管，摇落池台高怀。","岁寒共守，胜看人、调鼎费羹材。","认取逋山斜，月莫教、鹤梦轻猜。"]},{"t":"御街行 送春","f":"古风","c":["谁家故苑东风，树楼阁、花深护。","惯将芳恨语流莺，不惜花枝高处。","那堪一夜，人閒春梦，百啭留难住。","夕阳流水漂香去，残泪纷如絮。","画阑十二可怜春，无奈借人歌舞。","黄昏易散，沈沈帘影，一片西山雨。"]},{"t":"高阳台 己酉重午西园饮席感怀","f":"古风","c":["梅雨团金，兰风洒翠，吟觞又汎香蒲。","斗草阑干，馀薰更涤芳裾。","宫魂枉续长生缕，误旧情、臂约红疏。","感年光，明镜波心，不铸颜朱。","汨罗一片伤心碧，作中流箫鼓，遗恨江鱼。","清些难招，沈哀欲变吴歈。","江潭自古蛟龙恶，但怨魂、绿老汀菰。","镇销凝，节物凄凉，午醉谁扶。"]},{"t":"鹧鸪天 见旧家楼上燕巢感忆","f":"古风","c":["寂寞梁尘翠柳萦，隔花曾听下帘声。","绸缪去补谁家屋，飘泊今怜故主情。","泥堕处，旧闻筝。","春风秋月总堪惊。","谢堂只是寻常见，未信巢林误此生。"]},{"t":"竹马子","f":"古风","c":["寻桥柳荒泾，城芜古苑，去波孤艇。","见帆明渚鸟，镫昏驿树，岚光催暝。","陡觉画角生，哀秋声在，水际空离景。","对此恋前游绕，回阑凭断，斜阳红冷。","万感成幽阻，良辰易失，赏心难并。","天涯顿雪双鬓。","愁入西风凄哽。","但忆旧扇歌尘，小屏诗梦，人隔潇湘迥。","尊前雁落，满目关山影。"]},{"t":"阳台路 送客晚归城西陂揽景成咏","f":"古风","c":["暮山远。","见倒空翠湿，云开萍面。","荡荒湾、雨气衰荷，秋在水灯红飐。","愁杀渡江人，醉里解携，梦随波转。","离声断。","又暗催、湘弦鸿阵零乱。","独绕横桥归路，澹一水、漂花旧苑。","片帆风影，尚映带、凭高阑槛。","销魂又、寒林堕月，寂寞小城西畔。","空帘捲。","乱虫天、如闻哀叹。"]},{"t":"八声甘州 江皋野宴重别龙马里叟","f":"古风","c":["度高城、夕吹抵阳关，一声九迥肠。","正霜堤衰柳，烟汀堕蕙，梦落苍茫。","到此登临送远，揽景惜离觞。","满眼沧波泪，流尽三湘。","同是江湖蓬转，奈庾愁染鬓，空点吴霜。","羡秋篷归钓，犹及著芙裳。","想芳洲、蘋花自采，但寄情、鸥鹭莫相忘。","空凝伫，楚天孤雁，寂历南翔。"]},{"t":"兰陵王","f":"古风","c":["垄楸直，西向鱼山更碧。","残阳外衰草乱鸦，犹作苍茫阵云色。","归魂念报国。","空识青蝇吊客。","英雄泪，长使满襟，花落荒丘委三尺。","丰碑感陈迹。","剩藓墨留铭，樵采分席。","城南空见乌争食。","嗟百战身世，一抷榛莽，邯郸今古梦里驿。","眺风雨原北。","哀恻。","古怀积。","但乐府声流，旋凯歌寂，啼鸰夜月悲何极。","更玉树同壤，紫庭孤笛。","千秋华表，有坠露、带恨滴。"]},{"t":"瑞鹤仙","f":"古风","c":["桂丛香到枕。","渐透帘蛩语，凉烟催暝。","林容早霜近。","悄江天过雁，庭阶红冷。","重门夜迥，锁秋声、诗愁万顷。","更冥冥、满地歌尘，拍遍画阑谁应。","还听。","颓檐飞雨，乱叶昏灯，替人幽哽。","羁魂未醒。","奈犹是，去年病。","叹人閒有限，凄凉风物，偏与多情管领。","莫吟残、镜里花枝，梦来照影。"]},{"t":"拜星月慢 秋夜闻笛和清真","f":"古风","c":["润逼烟纱，凉添山枕，待月帘阴竹暗。","笛语飘来，隔灯痕邻院。","怅流景，渐觉、银床玉簟疏冷，露叶霜花明烂。","照水秋魂，绕空廊谁见。","镜屏中、尚识吴娘面。","无人唱、暮雨清尊畔。","莫问翠冶红骄，总行云催散。","燕重来、寂寞西风馆。","年华泪、锦瑟闻长叹。","但梦地、百转飙轮，触回肠欲断。"]},{"t":"踏莎行","f":"古风","c":["曳柳蝉疏，黏莎萤小。","过云流响初鸿到。","上灯花影隔窗深，下帘月气侵阶悄。","琴思吟销，茶香梦袅。","露床滴翠凝清筱。","年光有味是新凉，不堪独夜悲秋早。"]},{"t":"六丑 芙蓉谢后作","f":"古风","c":["又年芳催老，悄立遍阑干危碧。","怨花后期，无言花暗泣，黦地谁惜？","更洒黄昏雨，水环风佩，数断红消息。","罗裳自染秋江色。","穗帐才遮，珠茵旋积。","盈盈，怎堪搴摘？","只轻朱薄粉，愁上簪帻。","西园霜夕，照清池宴席。","步绮淩波地，成往迹。","尊前换尽吟客。","纵仙城梦见，玉颜非昔。","钗钿坠似曾相识。","终不向一镜东风媚晚，鬓边狼藉。","飘零恨独在江国。","怕旧题锦段重重泪，无人赠得。"]},{"t":"彩云归 九日城东亭登高","f":"古风","c":["危亭锁翠倚崇冈。","带虚岚、故国斜阳。","看冷枫、暮色馀霞散，波路迥、暝入秋乡。","更堪催、小城寒信，到西风雁行。","向此念、旧游天远，立尽昏黄。","茫茫。","登临百感，镇销凝、海涨尘荒。","昨宵酒醒，何处残笛，又绕空梁。","甚百年、悲秋未了，只恁风物凄凉。","伤心是、簪到黄花，绿鬓先霜。"]},{"t":"雪梅香 亭皋见月旷然起故园之思","f":"古风","c":["雨初歇，凭高极目送荒寒。","揽征蓬千里，烟光澹著愁颜。","秋尽林皋到残月，夜明楼阁起虚澜。","雁声落，笛里人家，犹梦关山。","无端。","换离景，一片伤心，画出应难。","水阔天低，望中故国云还。","乱叶从风诉飘泊，晚花凝露泪阑干。","归来后、满镜清霜，肠断谁看。"]},{"t":"踏莎行","f":"古风","c":["树老知门，山寒近屋。","一年风物供吟足。","秋声到地总无名，和愁题上阑干曲。","梦换纱棂，吟残画烛。","空阶雨断蛩声续。","霜前篱菊为谁黄，人閒秋鬓无重绿。"]},{"t":"夜半乐 秋尽夜闻雨有怀","f":"古风","c":["暝寒中酒情味，江天漠漠，秋尽仍连雨。","绕旧绿阑干，觅愁无处。","砌蛩乍咽，城乌旋起，满廊黄叶飘零。","散风还聚。","背暗烛、敲帘作人语。","夜窗又到雁阵，独掩低帏，更添沈炷。","霜堞隐，羌笳凄凄危曙。","泪凝丛菊，魂萦蔓草，几回梦里登临，乱山歧路。","渺京国、苍茫见烟雾。","此际追感，少日狂游，旧家歌舞。","念俊约，经时动离阻。","恁萧条，空叹雪满梁园赋。","惊岁事、一卧沧江暮。","画楼天远孤云去。"]},{"t":"庆春宫 冬绪羁吟","f":"古风","c":["红叶家林，苍烟邻寺，岁残未了秋声。","门柳鸦寒，庭莎蚕老，浸霜月气冥冥。","夜窗灯晕，镇摇落山川旧情。","伤心年事，何限繁华，不抵飘零。","追思结客幽并，连骑云骄，看剑星横。","谁分萧条，哀时词赋，过江无泪堪倾。","暮鸿天远，奈重拍燕歌自惊。","一生怊怅，拼与江南，空老兰成。"]},{"t":"雪梅香 梦半塘老人","f":"古风","c":["影悽寂，虚梁落月暗惊逢。","怅孤鸿天外，哀弦响绝秋空。","遗世高情谢猿鹤，过江馀泪送蛟龙。","叙愁阔，少别千年，犹是悤悤。","幽踪。","旷延伫，薜雨萝烟，夜啸谁同。","送客衰兰，漫悲旧曲回风。","故国伤心渺天北，暮云何意恋江东。","沈沈恨、一枕关山，魂绕青枫。"]},{"t":"念奴娇 己酉除夕","f":"古风","c":["夜阑酒醒，纵天涯，有梦无家归得。","三十年来，怊怅地，最是销魂今夕。","旧沥梅灰，新笼竹火，节物供愁色。","寒窗灯在，隔年红泪犹滴。","谁分有限生涯，伤心馀事，作江南词客。","只道东风能换世，肠断故园消息。","蛮雪零笺，燕尘衰帽，触绪增悽寂。","朝来看镜，对花空笑头白。"]},{"t":"石州慢 水边篱落忽见横枝病起寻春感时悽异","f":"古风","c":["竹外横斜，犹是去年，春在江国。","垂垂雪老烟疏，一树暗催头白。","西崦旧赏，总误天际轻阴，山桥谁倚伤心碧。","怊怅又黄昏，但诗痕愁觅。","追忆。","故宫春梦，点额人归，坠钿消息。","空有翠禽，啼恨花间曾识。","璚枝未寄，那更连雨凄寒，飘零不待南楼笛。","绕树再来看，怨东风无力。"]},{"t":"念奴娇 友人见示江南春图兼寄金陵怀古之什感事因题","f":"古风","c":["酒旗风影，漾回波，不断春愁千斛。","中有过江，名士泪，销得新亭一掬。","老子婆娑，英雄割据，莫举伤高目。","江南春好，送人惟有哀曲。","谁念玉尘风流，虚元谈未，了神州沈陆。","空吊金城衰柳色，依旧江潭悽绿。","故国鹃声，荒山龙气，终古苍黄局。","歌尘如梦，野花开遍陵谷。"]},{"t":"祭天神 题归鹤图为彊村翁作","f":"古风","c":["叹岁寒残雪谁堪语。","换苍苔、旧步荒江桥上路。","西园梦后重寻，剩有閒鸥侣。","奈沧江照影依依，阶前舞。","寂寞送、孤云去。","漫追惜、仙客归来误。","江山在，人物改，一霎成今古。","念茫茫、虫沙陈迹，天海风声，独立斜阳，自断淩霄羽。"]},{"t":"满庭芳 庚戌除夜听雨守岁，有怀京师风物之盛，荏苒三十馀年，无一到眼，天时人事有足悲者，今夕何夕，不觉老怀之枨触也。","f":"古风","c":["街鼓新雷，衣篝香雾，岁华销尽愁边。","小城梅讯，春思破蛮笺。","更听疏林过雨，寒宵伴孤鹤无眠。","空赢得，屠苏饮分，一醉老来便。","悽然，催向晓，绿窗儿女，还拥灯前。","怕新披历日，惊换星躔。","长记神京瑞景，何时再，云物瞻天。","今休说，松风闭户，犹有著书年。"]},{"t":"阳春曲 忆梅西崦","f":"古风","c":["晚来风，朝来雨，心事问春谁托。","一坞雪垂垂，西崦路、梦地经惯被花觉。","暝寒犹恶。","看未足、野桥疏萼。","须信旧识青山，胜伤春、等閒篱落。","记歌绕珍丛，行云暮。","曾倚竹、空怜翠薄。","而今遗芳独坐，怨书期、诉与辽鹤。","扁舟奈有素约。","怕笛里、江城萧索。","待扶醉、满把东风影，沈沈夜酌。"]},{"t":"阳春曲 春江题梦","f":"古风","c":["绮罗丛，芳菲节，春到梦中乡国。","凝澹画楼人，行云断、翠袖重倚暮寒恻。","几年相忆、曾醉蹋、凤城灯夕。","谁念繫月黏花，仗东风、总愁无力。","怅流水钿车，繁华地。","空冷落、珠尘绮席。","天涯伤春不见，剪梅枝、怨寄遥驿。","凭阑对此叹息。","更泪尽、离亭残笛。","看归雁、更带冥冥雨，西山自碧。"]},{"t":"浣溪沙 春雨渡江有忆","f":"七言古诗","c":["一雨春江遍绿莎，去帆风疾晚生波，乱流欲渡奈愁何。","长是人情不如鸟，青禽填海鹊填河，纵成遗恨也情多。"]},{"t":"浣溪沙 闻雨忆山中春事","f":"七言古诗","c":["旧泊湖亭唱蹋莎，暗香添酒泪添波，两山愁捐镜中螺。","莫待登临伤往事，更无哀乐费清歌，一年风雨为春多。"]},{"t":"卜算子 辛亥岁始春，故人治舟相约观梅于邓尉诸山，雨雪载涂，余以畏寒不出，因忆山中讨春旧游，次韵白石道人梅花八咏以示同志，一丘一壑自谓过之，若所作则伧歌无复雅句也。 其一","f":"古风","c":["低唱暗香人，旧识淩波路。","行尽江南梦里春，老兴天悭与。","桥上弄珠来，烟水空寒处。","万顷颇黎烂玉盘，月好无人赋。"]},{"t":"卜算子 辛亥岁始春，故人治舟相约观梅于邓尉诸山，雨雪载涂，余以畏寒不出，因忆山中讨春旧游，次韵白石道人梅花八咏以示同志，一丘一壑自谓过之，若所作则伧歌无复雅句也。 其二","f":"古风","c":["瑶步起仙尘，钿额添宫样。","一闭松风水月中，寂寞空山赏。","诗版旧题香，盛迹成追想。","花下曾闻玉辇过，夜夜青禽唱。"]},{"t":"卜算子 辛亥岁始春，故人治舟相约观梅于邓尉诸山，雨雪载涂，余以畏寒不出，因忆山中讨春旧游，次韵白石道人梅花八咏以示同志，一丘一壑自谓过之，若所作则伧歌无复雅句也。 其三","f":"古风","c":["数点岁寒心，百尺苍云覆。","落尽高花有好枝，玉骨如诗瘦。","卧影近池看，露坐移尊就。","竹外何人倚暮寒，香支和衣透。"]},{"t":"卜算子 辛亥岁始春，故人治舟相约观梅于邓尉诸山，雨雪载涂，余以畏寒不出，因忆山中讨春旧游，次韵白石道人梅花八咏以示同志，一丘一壑自谓过之，若所作则伧歌无复雅句也。 其四","f":"古风","c":["枝亚野桥斜，香暗岩扉迥。","瘦出花南几尺山，一坞苍苔静。","梦老石生芝，开眼皆奇景。","大好青山玉树埋，明月前身影。"]},{"t":"卜算子 辛亥岁始春，故人治舟相约观梅于邓尉诸山，雨雪载涂，余以畏寒不出，因忆山中讨春旧游，次韵白石道人梅花八咏以示同志，一丘一壑自谓过之，若所作则伧歌无复雅句也。 其五","f":"古风","c":["一棹过湖西，曾载双崦雪。","蹋叶寻花到几峰，古寺诗声彻。","林卧共僧吟，树老无花折。","何必桃源别有春，心境成孤绝。"]},{"t":"卜算子 辛亥岁始春，故人治舟相约观梅于邓尉诸山，雨雪载涂，余以畏寒不出，因忆山中讨春旧游，次韵白石道人梅花八咏以示同志，一丘一壑自谓过之，若所作则伧歌无复雅句也。 其六","f":"古风","c":["刻翠竹声寒，埽绿苔文细。","四壁花藏一寺山，香国閒中味。","对镜两蛾颦，想像西施醉。","欲唤鸱夷载拍浮，可解伤春意。"]},{"t":"卜算子 辛亥岁始春，故人治舟相约观梅于邓尉诸山，雨雪载涂，余以畏寒不出，因忆山中讨春旧游，次韵白石道人梅花八咏以示同志，一丘一壑自谓过之，若所作则伧歌无复雅句也。 其七","f":"古风","c":["云叠玉棱棱，琴筑流澌咽。","漫把南枝赠北人，陇上伤今别。","秀麓梦重寻，泉石空高洁。","台上看谁卧雪来，独共寒香说。"]},{"t":"卜算子 辛亥岁始春，故人治舟相约观梅于邓尉诸山，雨雪载涂，余以畏寒不出，因忆山中讨春旧游，次韵白石道人梅花八咏以示同志，一丘一壑自谓过之，若所作则伧歌无复雅句也。 其八","f":"古风","c":["初月散林烟，近水明篱落。","昨夜东风犯雪来，梦地春抛却。","最负五湖心，不为风波恶。","笑看青山也白头，一醉花应觉。"]},{"t":"念奴娇","f":"古风","c":["夜寒鹤梦，正沈沈，云海犹呼愁侣。","自见伤春，花溅泪，此恨都无年数。","笛步波遥，诗痕雪在，曾卧山楼雨。","苔阑如绣，胜看纱影笼句。","长忆一别文园，蜀弦肠断，空送孤云去。","欲寄陇头春不到，绿遍行吟烟浦。","古寺遗芳，小桥疏影，留伴樵风住。","游尘重省，乱花多少歧路。"]},{"t":"瑞鹤仙 落梅","f":"古风","c":["虎山桥下水。","问几时销尽，伤春清泪。","花前旧吟袂。","绕阑干如梦，东风还是。","相思未寄，荐青尊、高寒自倚。","恁飘零、画角声中，忍见送春桃李。","何意。","烟横雪乱，数点芳心，为谁憔悴。","苔茵漫缀。","无人见，断魂地。","叹垂垂一树，江南遗恨，不到灵均楚佩。","但黄昏、写照空池，两三瘦蕊。"]},{"t":"摸鱼子 小城晚眺","f":"古风","c":["压危阑乱山空翠，尽成衣上云雾。","坏宫芳草寻常见，不用凭高怀古。","回首处，渺一发，中原挂在斜阳树。","伤春更苦，想璚岛花飞，玉楼帘捲，天半起箫鼓。","苍茫里，时有东风雁度，沈沈辽海归路。","已怜柳色悽羌笛，犹报玉关春阻。","江上暮，又落絮，吹愁散作千家雨。","吴魂自语，但满地惊波，两三点雪，栖老旧鸥鹭。"]},{"t":"念奴娇 秋雨连江哀时书事","f":"古风","c":["旧家楼阁，剩斜阳，一线沈沈帘影。","海上忽闻，风雨至，平地奔涛千顷。","大泽鸿哀，荒涂龙战，身世沧洲迥。","尘中回首，五湖何处烟艇。","因念蜀客船回，高江急峡，泪湿听猿枕。","不待山川摇落后，秋气都成悲境。","衰草连云，惊烟到海，洒袂西风冷。","飞轮肠转，夜阑残梦谁醒。"]},{"t":"早梅芳近 辛亥中秋后三日，澹庵招同彊村汎舟，越来溪寻石湖居士故迹，自横塘载月而归。","f":"古风","c":["水荭疏，霜叶冷，一塔招提境。","歌钿尘断，画舸波閒见明镜。","故桥鸥鹭迹，坏壁龙蛇影。","看云归鸟没，客思正孤迥。","缓清觞，揽素景。","秋倦登临兴。","侵溪渔火，蹋月菱讴半烟暝。","泪添波入酒，梦破山横枕。","漫重来，载愁湖上艇。"]},{"t":"临江仙引 九日有怀瞻园，时方辟兵海上，用耆卿仙吕宫赋此。","f":"古风","c":["暝蹋小城路，乱鸦策策，班马萧萧。","暮尘起、时闻鼓角荒谯。","漂摇，对江树冷，墟烟悄，落日渔樵。","伤心地，正万方多难，潦倒登高。","魂销。","衰兰委佩，回首清些难招。","念东门、芜废北渚萍飘。","萧条。","叹茱萸会，风波阻，去国迢迢。","悲秋泪，换满江酃渌，胸块谁浇。"]},{"t":"庆春宫 同羁夜集秋晚叙意","f":"古风","c":["霜月流阶，芜烟衔苑，戍笳愁度严城。","残雁关山，寒蛩庭户，断肠今夜同听。","绕阑危步，万叶战风涛自惊。","悲秋身世，翻羡垂杨，犹解先零。","行歌去国心情，宝剑凄凉，泪烛纵横。","临老中原，惊尘满目，朔风都作边声。","梦沈云海，奈寂寞鱼龙未醒。","伤心词客，如此江南，哀断无名。"]},{"t":"水龙吟 送秋","f":"古风","c":["故国从此无花，可怜秋尽谁家苑。","连城江气，伤心一白，飞蓬梦远。","鹤老云孤，虫悽天瘦，岁寒空恋。","怪西风容易，者般摇落，争留待东风转。","不信江南肠断，放哀歌、楚声先变。","山川犹是，英雄安在，登临恨晚。","野戍残燐，江烽危照，苍茫望眼。","但愁波，到海何人，借与快并刀剪。"]},{"t":"水龙吟","f":"古风","c":["我怀栗里高风，醉来无复逃名地。","黄农宇宙，荒唐一梦，人閒何世。","八表同昏，孤云自远，茫茫天意。","叹沧江白发，酒醒甚处，空回首山河异。","直道伤心往事，百年中、眼看能几。","如何转烛，支离南北，馀生至此。","落木悲秋，残尊送腊，感时危涕。","念故山，薇老谁歌，采采向斜阳里。"]},{"t":"永遇乐 春夜梦落梅感忆因题","f":"古风","c":["江驿迢迢，片时枕上，春事如许！","乱插晴霄，低横野水，凄断东风主。","枝北枝南，眼看摇落，不为翠禽啼住。","揽遗芳璚瑰满抱，觉来顿成今古！","虚堂酒醒，倾城消息，误尽故山风雨。","玉砌雕阑，伤心还见，繫马郊园树。","人閒空有，晓寒一曲，谁信隔纱烟语？","恁凄凉南楼夜笛，送春旧处。"]},{"t":"水龙吟 人日寻梅吴小城有怀关陇旧游","f":"古风","c":["故宫何处斜阳，只今一片销魂土。","苍黄望断，虚岩灵气，乱云寒树。","对此茫茫，何曾西子，能倾一顾。","但水漂花出，无人见也，回阑绕空怀古。","别有伤心高处，折梅枝、怨春无主。","陇头人在，定悲摇落，驿尘犹阻。","报答东风，待催羌笛，关山飞度。","甚西江，旧月夜深，还过为予清苦。"]},{"t":"菩萨蛮 其一","f":"古风","c":["宫花不见人憔悴。","朝朝洗面燕支泪。","楼阁易斜晖。","绿尘筝雁飞。","空阶销玉冷。","燕立秋千影。","隔院骑声来。","卧屏红扇开。"]},{"t":"菩萨蛮 其二","f":"古风","c":["小波秋冷夫容苑。","鸳鸯头白花应见。","山黛可怜颦。","故宫眉样新。","有人妆澹薄。","缟袂垂深幕。","青鸟蓦飞来。","报君双凤钗。"]},{"t":"菩萨蛮 其三","f":"古风","c":["画楼残点和箫咽。","镜中愁见人如月。","双陆赌金环。","别时相赠难。","旧红宽臂缕。","妆罢长无语。","明日斗花风。","为谁梳洗浓。"]},{"t":"菩萨蛮 其四","f":"古风","c":["年年织锦红窗老。","绣裙空染南园草。","梦里送香车。","好春归别家。","手栽池上树。","难系斑骓驻。","悔不种夫容。","花时还妒侬。"]},{"t":"菩萨蛮 其五","f":"古风","c":["移家爱住青溪里。","东风绿尽湔裙水。","残雪驿桥西。","浅深郎马蹄。","花前和泪送。","鸾带行烟重。","梦断锦衾知。","晓寒孤起时。"]},{"t":"菩萨蛮 其六","f":"古风","c":["瑶台长是游仙驻。","残金销尽雕轮路。","帐殿柳如烟。","水飘花满船。","惊波风雨急。","夜夜青禽泣。","只道海能填。","西山无石衔。"]},{"t":"菩萨蛮 其八","f":"古风","c":["过花帘燕惊红落。","一床残梦东风薄。","春老不还家。","刺桐墙外花。","江南沙草暖。","镜水歌眉浅。","双篴出烟萝。","画船凉月多。"]},{"t":"菩萨蛮 其九","f":"古风","c":["平江风色连三月。","夜寒又近红楼别。","无酒莫伤春。","新年见旧人。","安排双泪眼。","长送春波晚。","斜月过西池。","隔阑花自移。"]},{"t":"玉楼春 其一","f":"七言律诗","c":["梅花过了仍风雨。","著意伤春天不许。","西园词酒去年同，别是一番惆怅处。","一枝照水浑无语。","日见飞花随水去。","断红还逐晚潮回，相映枝头红更苦。"]},{"t":"玉楼春 其二","f":"七言律诗","c":["因循游计春过半。","几度黄昏歌酒散。","此时泪眼向花枝，不待飘零肠已断。","旧游台榭年芳换。","却为伤高重倚遍。","水裙油幕趁清明，招得春魂何处见。"]},{"t":"玉楼春 其三","f":"七言律诗","c":["游丝抵死因风转。","绕遍天涯犹恨短。","一春醉梦误人归，残酒醒时春又晚。","笑声谁在秋千半。","蹴起飞花红一片。","衔花燕子不知愁，暗度芳心过别院。"]},{"t":"玉楼春 其四","f":"七言律诗","c":["晓莺帘外啼红处。","明月不留花影住。","起来弄篴过西桥，宿粉狂香吹满路。","路人不惜春心苦。","贪逐韶光过百五。","杏墙残萼待归簪，深雨闭门花乱舞。"]},{"t":"浣溪纱 其一 清明载酒山塘重记所见","f":"七言古诗","c":["花气温温趁橹柔。","禁烟晴昼水如油。","酒边残梦十三楼。","暂见不如成久别，旧欢无计破新愁。","来时春草去时秋。"]},{"t":"浣溪纱 其二 清明载酒山塘重记所见","f":"七言古诗","c":["斜日朱楼对捲帘。","篴中人意柳纤纤。","乱丝著地被愁黏。","花影蹋歌红步障，水香试酒白凉衫。","一春费泪与江南。"]},{"t":"浣溪纱 其三 清明载酒山塘重记所见","f":"七言古诗","c":["池馆新晴语细禽。","堕钗曾傍药阑阴。","经年同梦不同心。","近水吹香春澹薄，移花步影夜清沉。","月圆时节到而今。"]},{"t":"浣溪纱 其四 清明载酒山塘重记所见","f":"七言古诗","c":["拂水东风剧有情。","柳花当面化流萍。","天涯吟鬓几时青。","残烛已销无用泪，清歌犹作奈何声。","西楼人去恨长醒。"]},{"t":"采桑子 其一","f":"古风","c":["凭高满面东风泪，独立江亭。","流水歌声。","销尽年涯不暂停。","归来自掩香屏卧，残月新莺。","梦好须惊。","知是伤春第几生。"]},{"t":"采桑子 其二","f":"古风","c":["销魂最是皋桥水，花雨冥冥。","歌泪盈盈。","不解西流总费声。","画船烟泊经游地，灯火高城。","弦管残更。","无奈明朝酒易醒。"]},{"t":"三台令 其一","f":"古风","c":["春雨。","春雨。","滴到无声更苦。","红楼酒醒天涯。","相送舟前落花。","花落。","花落。","还较去年轻薄。"]},{"t":"三台令 其二","f":"古风","c":["春水。","春水。","流尽一年花泪。","绿阴明日池塘。","可待重来断肠。","肠断。","肠断。","重来茜窗人澹。"]},{"t":"浣溪纱 其一","f":"七言古诗","c":["著酒芳心不自持。","小云双枕带花移。","今年春早梦先知。","梅萼有情红到骨，柳条无恨翠舒眉。","水堂新月旧相期。"]},{"t":"浣溪纱 其二","f":"七言古诗","c":["无事伤心独费情。","落梅风里掩重扃。","春衣一桁细香零。","词谱当歌和泪教，镫窗无睡枕肩听。","水边花外雨冥冥。"]},{"t":"谒金门 其一","f":"古风","c":["烟浪恶。","花满海山楼阁。","辽鹤无书云漠漠。","故宫春梦薄。","莫惜舞人零落。","长袖为君重著。","堕地鸾钗成密约。","捧觞千日乐。"]},{"t":"谒金门 其二","f":"古风","c":["花窣地。","红玉枕山云腻。","良夜好天浓睡里。","蜡盘空转泪。","妾似杨花飘坠，郎是一江春水。","容易东风无好计。","少年须著意。"]},{"t":"谒金门 其三","f":"古风","c":["钗凤坠。","人意不如初会。","圆月后逢歌舞地。","断肠明镜里。","早是君心难恃，恨不玉颜先悴。","恩重娇多情易费。","枕函花有泪。"]},{"t":"浣溪纱 其一 乙未山塘寒食","f":"七言古诗","c":["春半馀寒未减衣。","绿莎汀溆燕来稀，梦期何事镇相违。","一簇帘花残月地，数行门柳宿烟枝，画船灯火夜归迟。"]},{"t":"浣溪纱 其二 乙未山塘寒食","f":"七言古诗","c":["斗草阑干晚棹移，好风香出画罗衣，隔花临水见腰肢。","病枕久虚胡蝶梦，歌楼犹唱鹧鸪词，疏狂多误少年时。"]},{"t":"鹧鸪天 中秋后二日越来溪夜汎","f":"古风","c":["露脚斜波月上迟。","镜中曾见越来时。","湖光一片伤心碧，却与吴儿作水嬉。","飞画鹢，引金蠡。","罗旂香干烛龙随。","歌尘只是黄昏散，愁满风萝野粉吹。"]},{"t":"鹧鸪天","f":"古风","c":["岩桂秋香晚尚花。","顺阳旧墅问残霞。","五湖自送鸱夷去，风月依然属范家。","浮白劝，比红誇。","有人低唱倚蒹葭。","曲中解得销魂句，不羡溪头越女纱。"]},{"t":"踏莎行 其一 送子苾入陕","f":"古风","c":["连棹湖山，对床风雨。","吟坛十载更相主。","已怜憔悴尽中年，那堪离乱成孤旅。","鸥外吴云，马头秦树。","大江东去人西去。","严关百二旧经行，不愁梦失寻君处。"]},{"t":"踏莎行 其二 送子苾入陕","f":"古风","c":["压酒春灯，掩歌秋扇。","江南已是无肠断。","曲中莫作水风听，尊前便有关山怨。","经醉池亭，临分笺管。","西园芳草随人远。","黄金纵得赎蛾眉，胡沙应换春风面。"]},{"t":"踏莎行 其三 送子苾入陕","f":"古风","c":["蜀锦裁篇，吴皋飘寓。","佳游顿失城南侣。","桥边乌鹊纵分飞，陇头鹦鹉能言语。","柳雪官程，图书傢俱。","扁舟明日长安路。","多君一县好青山，支颐手板供愁句。"]},{"t":"踏莎行 其四 送子苾入陕","f":"古风","c":["南浦兰情，西崦梅讯。","好春良月离天近。","十年空负过江名，一官直抵飞花溷。","山县愁鬟，雪关衰鬓。","才人自断漂零分。","它时好载郁林归，只应片石销残恨。"]},{"t":"鹧鸪天 其一 余往来邓尉山中十馀年矣，独爱青芝一坞，林嶂秀岨，人迹罕至交，有终焉之志，未逮也。还泊西崦因赋是解","f":"古风","c":["树隐湖光望转明。","岩深晚桂尚飘馨。","十年秋鬓输山绿，依旧看山梦里行。","烟澹宕，月空冥。","下崦蒙雨上崦晴。","眠去无地青芝老，虚被樵渔识姓名。"]},{"t":"鹧鸪天 其二 余往来邓尉山中十馀年矣，独爱青芝一坞，林嶂秀岨，人迹罕至交，有终焉之志，未逮也。还泊西崦因赋是解","f":"古风","c":["结梦疏云泛渚蘋。","霜林秋色艳于春。","山中种树书堪读，世上繁华迹总陈。","惊岁晚，负閒身。","石芝鹤语旧知津。","红桑海畔花争发，一掬微波见绿尘。"]},{"t":"杨柳枝 其二","f":"七言绝句","c":["永丰坊半翠双枝。","和泪移来近玉墀。","不是伤春词客在，故宫谁解妒腰肢。"]},{"t":"杨柳枝","f":"七言绝句","c":["才作风花又水萍，一生好计只飘零。","可怜憔悴章台路，送尽离人眼尚青。"]},{"t":"谒金门","f":"古风","c":["行不得！","黦地衰杨愁折。","霜裂马声寒特特，雁飞关月黑。","目断浮云西北，不忍思君颜色。","昨日主人今日客，青山非故国。"]},{"t":"谒金门","f":"古风","c":["留不得！","肠断故宫秋色。","瑶殿璚楼波影直，夕阳人独立。","见说长安如弈，不忍问君踪迹。","水驿山邮都未识，梦回何处觅？"]},{"t":"谒金门","f":"古风","c":["归不得！","一夜林鸟头白。","落月关山何处笛？","马嘶还向北。","鱼雁沈沈江国，不忍闻君消息。","恨不奋飞生六翼，乱云愁似幕。"]},{"t":"杨柳枝","f":"七言绝句","c":["数行烟柳蓟门春，离袂经年惹曲尘。","莫为西风摇落早，灞陵犹有未归人。"]},{"t":"杨柳枝","f":"七言绝句","c":["长条如带水萦环，难繫离愁百二关。","羡尔巢林双燕子，秋来暂客尚知还。"]},{"t":"杨柳枝 其三","f":"七言绝句","c":["暂理愁眉试半妆，舞衣叠泪损宫黄。","晴丝绕遍天涯路，不为离人续断肠。"]},{"t":"杨柳枝 其四","f":"七言绝句","c":["回雪吹花唱大堤，弓腰斗罢梦长啼。","身轻不及枝头絮，犹逐东风舞向西。"]},{"t":"杨柳枝 其五","f":"七言绝句","c":["乱丝歧路苦愁萦，剪剪轻风别有情。","一夜雪绵吹满帐，教人春梦不分明。"]},{"t":"杨柳枝 其六","f":"七言绝句","c":["夹道分堤翠浪生，湖山歌舞总堪惊。","只今一片斜阳树，剩有宫鸦啼数声。"]},{"t":"杨柳枝 其七","f":"七言绝句","c":["烟洗风梳碧可怜，秋深犹咽五更蝉。","谁家残月沧波苑，时见渔舟网碎钿。"]},{"t":"杨柳枝 其八","f":"七言绝句","c":["故国年芳换绿尘，楼台多是别家春。","狂花一阵过无影，乱入宫城不避人。"]},{"t":"杨柳枝 其九","f":"七言绝句","c":["水明帐殿月如烟，翠楼连云挂玉泉。","香辇不回秋又晚，栖乌头白近霜天。"]},{"t":"杨柳枝 其十","f":"七言绝句","c":["破晓残莺出禁林，飞花寒食雨沈沈。","章台自台牵行色，莫为离多减路阴。"]},{"t":"杨柳枝 其十一","f":"七言绝句","c":["楼阁春深雪不寒，关山秋早笛初残。","一般画出伤心色，漫作隋堤落照看。"]},{"t":"杨柳枝 其十二","f":"七言绝句","c":["纤纤新翠带愁颦，零落弓弯旧舞人。","底事临风眠未起，灵和不是汉时春。"]},{"t":"杨柳枝 其十三","f":"七言绝句","c":["拂遍京尘窣地惊，风条雨叶不胜情。","西园已自无多树，一夜伤秋转费声。"]},{"t":"杨柳枝 其十四","f":"七言绝句","c":["平居谁分解伤春，竞赌长楸走马身。","寂寞空城飞絮尽，羌笳吹起六街尘。"]},{"t":"杨柳枝 其十五","f":"七言绝句","c":["高秋萧瑟思何堪，昔树空悲忆汉南。","任是婆娑生意尽，不辞风雪老江潭。"]},{"t":"鹧鸪天 其一 馀与半塘老人有西崦卜邻之约，人事好乖，高言在昔，款然良对，感述前游，时复悽绝。","f":"古风","c":["据榻连吟数往年，夜窗枥马警秋眠。","可怜燕市尊前月，又共吴云梦里天。","回首处，一潸然。","小山招隐有新篇。","淮南几树留人桂，纵得攀援不得仙。"]},{"t":"鹧鸪天 其二 馀与半塘老人有西崦卜邻之约，人事好乖，高言在昔，款然良对，感述前游，时复悽绝。","f":"古风","c":["秋老山桥虎气沈，霜风呼酒旧登临。","梵钟出树岩扉回，渔火通波雨坞深。","连棹路，五湖心。","别来三见冷枫吟。","白云定识非生客，莫枉芝崦鹤梦寻。"]},{"t":"鹧鸪天 其三 馀与半塘老人有西崦卜邻之约，人事好乖，高言在昔，款然良对，感述前游，时复悽绝。","f":"古风","c":["谏草焚馀老更狂，西台痛哭恨茫茫。","秋江波冷容鸥迹，故国天空到雁行。","诗梦短，酒悲长。","青山白发又殊乡。","江南自古伤心地，未信多才累庾郎。"]},{"t":"浣溪沙 其一 甲辰中秋后二日晚晴放舟石湖，观越城桥下☆月，明日将从胥口探桂山中，不预此游盖五年矣。","f":"七言古诗","c":["溪上曾闻渡越兵，乱流犹似怒蛙鸣，蒲风杉雨战秋声。","梧梦只今空故苑，菱歌依旧绕离城，长桥人散月孤明。"]},{"t":"浣溪沙 其二 甲辰中秋后二日晚晴放舟石湖，观越城桥下☆月，明日将从胥口探桂山中，不预此游盖五年矣。","f":"七言古诗","c":["花艳连桡度镜光，满湖丝管水飞香，月明何恨预兴亡。","莫揽清歌悲小海，更催秋梦落横塘，波空塔影自凄凉。"]},{"t":"浣溪沙 其三 甲辰中秋后二日晚晴放舟石湖，观越城桥下☆月，明日将从胥口探桂山中，不预此游盖五年矣。","f":"七言古诗","c":["烟夕凉波起白蘋，蔫红落粉尽歌尘，依稀山黛可怜颦。","一舸谁寻虾菜路，千丝空羡鲙残鳞，无多秋事属閒人。"]},{"t":"浣溪沙 其四 甲辰中秋后二日晚晴放舟石湖，观越城桥下☆月，明日将从胥口探桂山中，不预此游盖五年矣。","f":"七言古诗","c":["夜午看山旧寺楼，别来岩桂五经秋，好花凉月醉扶头。","一水又平桥畔路，几人曾预镜中游，山阳残笛更吹愁。"]},{"t":"浣溪沙 其五 甲辰中秋后二日晚晴放舟石湖，观越城桥下☆月，明日将从胥口探桂山中，不预此游盖五年矣。","f":"七言古诗","c":["听水听歌醉梦间，秋衣零露夜忘还，拍浮人与白鸥閒。","馀兴好探花里市，旧情不断枕边山，半篷风色过梅湾。"]},{"t":"浣溪沙 其六 甲辰中秋后二日晚晴放舟石湖，观越城桥下☆月，明日将从胥口探桂山中，不预此游盖五年矣。","f":"七言古诗","c":["旧泊横桥花覆船，酒灯人语隔湖烟，红箫肠断十年前。","经醉溪山如此夜，后逢花月奈何天，漫吟秋扇黯悽涟。"]},{"t":"蝶恋花 其一","f":"古风","c":["春雨晚来过一阵，送了清明，有限花番信。","又是伤春天气近，阴晴半日都难定。","见说好春新值闰，如梦如酲，依旧年时病。","人事音书谁与问，游丝舞絮空添恨。"]},{"t":"蝶恋花 其二","f":"古风","c":["几日层城春漏泄，小槛调莺，宛转新柔舌。","好梦不堪春后说，空林犹有啼鹃血。","兰麝罢熏山枕热，酒醒阑干，满面杨花雪。","羌管有情吹不彻，乱云过影中庭月。"]},{"t":"蝶恋花 其三","f":"古风","c":["花月一春供几醉，染柳熏梅，费尽铅华水。","帘幕尘尘如梦里，为谁断送伤心地。","不信东风能换世，过半韶光，怊怅无多事。","题泪花枝难远寄，燕莺空诉留春计。"]},{"t":"蝶恋花 其四","f":"古风","c":["落尽江梅春已半，浪蕊狂花，不到伤春眼。","一夜金铃消息断，只供蜂蝶喧尘乱。","陌上马蹄梁上燕，解惜香泥，已是韶红变。","斜日帘栊人不见，蘼芜雪老谁家苑。"]},{"t":"采桑子","f":"古风","c":["竹声到枕凉如许，翠湿纱幮，香断灯孤，冰簟银床一夜疏。","晓来独步穿花去，罗袂沾濡，满把明珠，始觉前溪过雨初。"]},{"t":"采桑子","f":"古风","c":["雨帘不捲初疑夜，梦地模糊，竹醉花扶，过枕茶声午睡馀。","故人久断江干信，借问庭梧，秋意何如，一日西风一日疏。"]},{"t":"蝶恋花 其一 己酉中秋夜雨","f":"古风","c":["好月一年能几见，待得圆时，抵死云遮遍。","可惜良宵天不管，酒灯暗雨深深院。","梧叶洒阶愁万点，不听清歌，已是无肠断。","旧节惟酬双泪眼，西阑一夜秋声满。"]},{"t":"蝶恋花 其二 己酉中秋夜雨","f":"古风","c":["长忆红楼离夜语，月满芳尊，赏月人遍去。","自见月圆无此苦，年年情恨天难补。","欲唤姮娥凭说与，泪湿花枝，故作黄昏雨。","后夜相看肠断处，一弯又被愁眉妒。"]},{"t":"杨柳枝 其一 赋小城梅枝","f":"七言绝句","c":["谁家笛里返生香？","倾国风流解断肠。","头白伤春无限思，不应此树管兴亡。"]},{"t":"杨柳枝 其二 赋小城梅枝","f":"七言绝句","c":["到地春风不肯閒。","南枝吹尽北枝残。","吴宫多少伤心色，占得墙东几尺山！"]},{"t":"杨柳枝 其三 赋小城梅枝","f":"七言绝句","c":["采香径里晚烟空，濯粉池边晓露丛。","一样故宫春寂寞，可怜无地看东风！"]},{"t":"杨柳枝 其四 赋小城梅枝","f":"七言绝句","c":["缟衣月下见前身，隔世惊逢绝世人。","怊怅溪南数枝雪，为谁开落与江春？"]},{"t":"杨柳枝 其五 赋小城梅枝","f":"七言绝句","c":["轻朱薄粉试妆新，漫比西施镜里春。","可惜君王残霸业，只教换得两蛾颦。"]},{"t":"杨柳枝 其六 赋小城梅枝","f":"七言绝句","c":["江树犹伤旧国春，肯因冷澹与时新。","风来谁撼千林雪，一洗人閒桃李尘。"]},{"t":"杨柳枝 其七 赋小城梅枝","f":"七言绝句","c":["万枝寒玉照溪桥，鹤语今年雪未销。","自占东风故城曲，凄凉烟月属前朝。"]},{"t":"杨柳枝 其八 赋小城梅枝","f":"七言绝句","c":["一点芳心作意酸，预知年事有彫残。","只应从此无花著，胜与松筠守岁寒。"]},{"t":"虞美人 其一","f":"古风","c":["西园旧是苍波苑。","几度临花宴。","蓬莱宫阙总生尘。","犹有一湖春色解留人。","当年湖上游仙迹。","换得伤心碧。","麝尘蠹粉满亭池。","怊怅倚帘人去未多时。"]},{"t":"虞美人 其二","f":"古风","c":["倾城一片宫沟水。","春皱波难起。","夜闻风雨葬倾城。","须信人閒天上等飘零。","雕轮宝马城西路。","转烛空烟雾。","流莺休觅上阳花。","已是绿阴芳草遍人家。"]},{"t":"虞美人 其三","f":"古风","c":["楼台返照空明镜。","更落西山影。","狂香野粉满天愁。","断送东风一剪水西流。","朝朝洗面燕支泪。","染作丹棱水。","凄凉还问画中人。","谁分故园从此见残春。"]},{"t":"绛都春 赋壶园雁来红","f":"古风","c":["鹃魂一片。","怪小墅绿阴，都被愁染。","鸿阵悄来，凄紧西风黄昏院。","茜裙残缕吹香远。","却醉入、秋娘心眼。","梦回沟水，红情自老，误他题怨。","还见。","披烟浣露，正灯暗绛屏，和泪妆点。","霜信曼催，吴锦飘零无人剪。","可怜生是江南晚。","更解替、幽花肠断。","几回立尽斜阳，故山冷艳。"]},{"t":"河传","f":"古风","c":["凄雨。","无绪。","绿窗閒。","春去如烟梦还。","晓屏绣云山外山。","弯环。","忆他眉黛寒。","十二朱阑凭恨遍。","魂已断。","又向星前见。","冷香阶。","红没鞋。","蝶来。","扑风花堕怀。"]},{"t":"风入松 江南秋早，丛桂未华，连雨困人，大似熟梅天气，吴侬呼为木樨蒸，赋此以志清异。","f":"古风","c":["古帘烟雨过梅黄。","又坐秋乡。","梦痕绿满西风树，未花开、先断人肠。","记向蕊宫亲折，姓名湿了天香。","翠阴楼阁澹金装。","小麝吹凉。","玉娘偷得潇潇谱，染吴丝、弹作清商。","一霎牵情主袖，几回消泪钿筐。"]},{"t":"南乡子","f":"古风","c":["柔舻小蘋乡。","牢记朱阑近水房。","偏是落红迷径曲，回廊。","觅著春风影亦香。","清靓睡时妆。","笑摘花钿裹绣裆。","肌麝不禁衣澹薄，新凉。","独自吹镫上玉床。"]},{"t":"鬲溪梅令","f":"古风","c":["堕怀凉月醒来空。","梦还逢。","人在垂杨影里唤青骢。","小楼裙衩风。","涉江何意采夫容。","冷香丛。","拾得蛮笺和泪署绡封。","露花秋自红。"]},{"t":"侧犯 天平山题壁","f":"古风","c":["乱峰倒立。","蹋空直与云呼吸。","奇极。","看列坐愁鬟许平揖。","尘飞不到处，人影和天碧。","幽觅。","正木落，千岩数声篴。","层巅石径，空照苍黄壁。","寻坏藓、旧诗痕，烟外翠如泣。","满袖松风，画秋无迹。","绿尽吴根，付谁收拾。"]},{"t":"倦寻芳 壶园夜雨用李秋崖韵同次湘","f":"古风","c":["小帘花瘦，废阁镫昏，孤咏何赖。","破碎壶天，哪管赋愁人在。","檐滴都无空绿泻，池流应有残红带。","到更阑，怕南来好梦，湿云全碍。","想几处、筝篷凄咽，乱点西风，飞上蛾黛。","便是秋声，一夜有情须买。","别泪销沈鸥社酒，浮根愁老鲑乡菜。","悔前宵，月明中，负他芳霭。"]},{"t":"清平乐 冷红阁醉题","f":"古风","c":["花枝倦拗。","红阵和愁扫。","帘外扶妆人俏俏。","镜槛瞥逢一笑。","湘帏乍揭冰绡。","近身花气如潮。","凉到一眉春月，梦痕绿上芭蕉。"]},{"t":"蝶恋花 甲申夏荷花生日，南荡舟中，遇太常仙蝶，以酒祝之，环袖三匝而去，歌以志异。","f":"古风","c":["花砑光摇三万顷。","醉吸天风，吹下春驹影。","灵蜕何缘同酩酊。","晚来历乱仙衣冷。","笑问祠官仙几等。","栩栩精魂，来證清凉境。","莫是红边残梦醒。","伴人冷醉枫江艇。"]},{"t":"满江红 再汎南荡，晚花向残，以南吕宫旧谱歌之。","f":"古风","c":["绀海文漪，荡不尽、花意万千。","销魂又、断桥西堍，零落歌钿。","白捲酒波双袖雪，绿浮诗梦一船山。","听闹红深处玉箫沉，风露寒。","秋灯外，柔橹边。","载香去，放愁还。","散袜罗馀绮，乱点蘋烟。","吴网难收残霸局，越云犹作丽娃鬟。","剩两三鸥迹，话芳尘，明镜閒。"]},{"t":"壶中天 从友人乞鹤","f":"古风","c":["青田大鹤，洞天边，记我梦云曾绿。","自见支公腾驭去，仙客也愁清独。","悽唳松寒，瘦唫梅老，谁倚南飞曲。","巢痕休问，故山残雪埋屋。","见说旧隐亭林，有丹歌引舞，窥人都熟。","欲乞孤云移素羽，几日相思对竹。","篴唤朝霞，珠衔明月，待向词仙祝。","蓬莱峰顶，看君招下鸾鹄。"]},{"t":"一箩金 题扬州女子静怜月底修箫谱障子","f":"古风","c":["镜里愁妆熏麝苦。","细玉参差，却替花魂语。","人瘦于花花尚妒。","冷香吹雪开庭暮。","罗袂禁寒谁伴汝。","曲曲阑干，曲到无凭处。","满把春星和梦数。","旧情红老东风树。"]},{"t":"好事近 赋水窗梅枝","f":"古风","c":["瘦绿觅诗痕，昨夜梦云犹湿。","谁坐茜窗开处，恰一枝横入。","芳魂还倩笛招来，两两翠禽集。","怕向石阑题句，有那人香迹。"]},{"t":"扫花游 江上早春短篷听雪悄然感赋","f":"古风","c":["年涯草草，又绿到江梅，暗吹残雪。","冻枝自折。","正风镫历乱，酒醒时节。","涴地芳华，倦客伤春更切。","笛边月。","唤一片梦云，都被愁叠。","幽事今杳绝。","记醉玉西湖，踏歌双楫。","乱花散叶。","作荒波皱翠，替人呜咽。","有限柔魂，曲里能销几别。","艳欢歇。","问吴鸥、旧情谁说。"]},{"t":"徵招 乙酉立春风雨忆梅西崦将作讨春小饮","f":"古风","c":["古帘暗雨江南绿，吹来梦痕都瘦。","旧物总翻新，只新愁如旧。","杜郎为客久。","漫吟老、莺前花后。","寂寞今朝，堆盘生菜，咬春时候。","孤负五湖心，吴尘里、轻寒暗疏歌袖。","短梦过风箫，怪销魂太骤。","一年芳事又。","怕零乱、梅花十亩。","正窥户、山髻招人，趁雪篷呼酒。"]},{"t":"台城路 见池上南枝有感","f":"古风","c":["翠奁栖影骄如雪。","相思五湖春阔。","闭雨閒门，人因花瘦，花更因谁瘦绝。","吟弦似咽，便唤起盈盈，那禁重折。","嫩约尘空，暗香应妒袖罗窃。","年时花里赋别。","玉鬟临水见，曾斗冰洁。","屧径荒踪，笙楼细语，愁入一眉斜月。","轻寒尚怯，甚歌口吹红，梦云都热。","残酒东阑，峭风苏倦蝶。"]},{"t":"钗头凤 花步里记所见","f":"古风","c":["屏山远。","兰期短。","小花照水吴妆浅。","红窗隙。","朱唇的。","旧家池馆，画春无迹。","觅。","觅。","觅。","悠然见。","飘然散。","玉笙鹤背天风断。","空亭立。","星前忆。","便伊香影，万珠量得。","值。","值。","值。"]},{"t":"祝英台近 金粟庵主人遇旧欢老伎慧珠，席上鼓琴，索题其秋弦话月图。","f":"古风","c":["澹妆收，残篆袅，斜月小坊静。","肠绕朱弦，春是曲中影。","分明一把愁丝，七条分理，替人语、声声凄哽。","好风景。","多定耽误知音，旧期总无准。","倦说心挑，梦也可怜境。","是谁指上离骚，赚他红泪，尽弹断、袖痕香冷。"]},{"t":"摸鱼儿 丙戌暮春洪阁学文卿将如京师饯以此曲","f":"古风","c":["又江南、落花时节，故人一别如雨。","酒镫分影沧波梦，变尽白云今古。","君莫舞。","更闻道、蓬莱西有仙槎路。","天风待举。","看兰雪吹襟，松霞劝盏，都恋五湖侣。","还记取。","十里金烟翠雾。","年年游衍佳处。","丛铃碎佩多瑶怨，分得半囊愁句。","君且住。","奈疏俊风怀，已是沾泥絮。","遍侬倦旅。","对花老荒钿，酒醒残篴，馀思渺南浦。"]},{"t":"徵招 题唐六如画黄茅熨斗枋山水卷子为易笏山年丈作","f":"古风","c":["天心独有难平处，飞来一峰孤峭。","七十二愁鬟，但罗罗云表。","任他娲炼巧，怕重有，烂柯人到。","唤起山灵，问谁持去，袖中青小。","乱礁镇无言，西崦外，摩挲断烟衰草。","不见采芝仙，剩沧州画稿。","笔端空翠绕，谩收拾，白云归老。","仗天际，壁立苍茫，破万波昏晓。"]},{"t":"木兰花慢","f":"古风","c":["乱山残雨夜，空送泪、下西楼。","正五月江城，一声风笛，为我先秋。","知不。","十年词赋，渐狂名换了雪盈头。","同调天涯几辈，独弦漫制新愁。","南游。","湖海盟鸥。","花影外、梦相酬。","叹昨夜歌尊，今宵吟袖，明日归舟。","休休。","旧题尘壁，过吴亭怕有断魂留。","剩取残衫恨墨，酒边清事都收。"]},{"t":"台城路 为吴子述题春眠听雨图","f":"古风","c":["鬓丝自织回肠谱，迷离乱愁还醒。","遗挂销尘，零弦语夜，又是断鸿幽哽。","风凄雨萦，念阔被虚帷，此怀偏省。","残点沈沈，五更暗烛吊清影。","江南好春似锦，怪鹃红易染，吹上孤枕。","云想翘鬟，花回秀靥，閒了旧时明镜。","谁研泪粉，便写出来生，倩魂难并。","梦短天长，倦吟成瘦沈。"]},{"t":"洞仙歌","f":"古风","c":["银塘雨过，似花弹冰汗。","水佩风环翠凉满。","画船回、十里明镜秋波，人一笑，红入鸳鸯阵乱。","夜来天袂冷，香步无尘，唤起唫鸾下霄汉。","七十二夫容、立尽仙云，珠槃泻、万星齐转。","且醉把、璚枝舞珊珊，道浴罢天池、羽衣新换。"]},{"t":"醉花阴 赋瞿园秋色分题得剪秋罗","f":"古风","c":["织尽吴云愁暗醒。","薄袖吹香冷。","梦老汉宫秋，一片残霞，又散江南锦。","红窗刀尺催霜紧。","坐晚妆凉靓。","莫问浣纱人，泪粉悽迷，湿透西风影。"]},{"t":"如梦令 题姑苏女子陈慰之眠琴绿阴小影","f":"古风","c":["帘额绿尘吹皱。","花落春如人瘦。","无绪理湘弦，睡起水沈沾袖。","僝僽。","僝僽。","风打小窗梅豆。"]},{"t":"台城路 文卿阁学奉使泰西海上赋别","f":"古风","c":["卧龙腾啸三山走，嘘成海天云气。","北斗重斟，西溟一吸，何羡安期高誓。","乘风万里。","载侠士仙姝，剪波同济。","回首蓬莱，指弹楼阁拓空起。","当年汛槎汉使，怪星边凿空，窥破天咫。","铗毂飞霆，艨艟掷火，泄尽千秋机事。","沧桑影底。","看鳌背英雄，几回如此。","百感茫茫，碧霄长剑倚。"]},{"t":"虞美人 丁亥秋八月十八日，石湖丳月，舟中客语小红故事，时同社方和白石暗香疏影二曲，馀情赋此，仍次姜韵，梦游之感，同一凄独也。","f":"古风","c":["歌云软绣吴篷背。","暗浦明珠翠。","旧家池馆久蒿莱。","说与鸥边凉月、带愁回。","长波西望垂虹路。","载雪吹箫处。","暗香不送倩魂归。","可奈湖山无恙、昔游非。"]},{"t":"霜花腴 补秋小阁夜饮","f":"古风","c":["冷红殢翠，怎等閒，星前暗放春逃。","珠幌回镫，玉阑呼酒，馀风约住笙箫。","夜花自骄，贮艳踪、金鸭重烧。","更谁家、好月飞来，倚妆同守可怜宵。","芳梦有情须断，尽歌云解护，莫便魂销。","秋点寒催，粉光浓觅，留仙不隔冰绡。","坠钿倦翘。","度悄吟、花气如潮。","怕朝霞、一掬愁痕，鬓边天样遥。"]},{"t":"满江红 和易菽由同白石韵","f":"古风","c":["骚佩横秋，蓦欲倒、词海万澜。","泠然想、满怀冰玉，镂刻神山。","冷咏但呼冲雪舫，远游何羡切云冠。","看一笺、吴锦织同心，歌赠环。","觞弦地，回首看。","醉云北，梦烟南。","算过江名士，二仲当关。","老我壶中閒日月，只宜黄绮姓名瞒。","待五湖、风笛唤寻盟，鱼鸟间。"]},{"t":"念奴娇","f":"古风","c":["海山仙使，又奴星小谪，来寄人庑。","一席烟波家世感，只有渔童堪侣。","锄药生涯，扫花门径，物外供吟谱。","封侯何羡，锦囊分得奇句。","偏念颖士风流，依依十载，也博怜才誉。","却笑豪门牙爪列，空作守钱庸虏。","赚子英雄，驱人岁月，老更书佣伍。","楚声谁和，命骚应亦吾许。"]},{"t":"菩萨蛮 其七","f":"古风","c":["镜堂前后花交见。","歌纨裁月难遮面。","憔悴问花枝。","玉颜非别时。","浅妆工薄媚。","弦上西风泪。","灯黯塞鸿归。","一声肠九回。"]},{"t":"少年游 其一 宿杭州凤山门外","f":"古风","c":["西兴山色隔江招。","眉翠妒春娇。","满地流花，一奁碎月，江国女儿潮。","年时嫩约湔裙侣，多在段家桥。","倦里笙歌，閒边镫火，总是可怜宵。"]},{"t":"少年游 其二 宿杭州凤山门外","f":"古风","c":["夫容和泪送流霞。","莫浣越溪纱。","水色帘衣，粉香窗扇，知醉那人家。","酒香红被东风影，吹梦又天涯。","一夜春潮，四山残雪，狼藉枕边花。"]},{"t":"三姝媚 秋晚新晴，买舟黄步，时闻易五中实卧病惠山，便一寻问，用梦窗韵赋此。","f":"古风","c":["夫容湖上道。","浣离痕青青，旧袍如草。","醉过重阳，叹故人轻别，雨冥风悄。","泪接长波，空一镜，鬓霜浓照。","玉篴谁家，还掩孤屏，暗吹秋调。","昨夜山眉晴扫。","趁唤酒吴亭，远寻幽窈。","露榭云廊，怕断魂重倚，倦迷清晓。","旧社飘萍，算几度、閒鸥同到。","莫更匆匆归去，吟湘自老。"]},{"t":"壶中天 庚寅中春，将予计车维舟胥渡，留别江东故人。","f":"古风","c":["江城暗雨，正残箫昏梦，客船无酒。","曲里香尘，吹不起，还误少年衫袖。","官烛烟寒，驿亭波暖，绿入清明柳。","玉人休折，小眉经岁疏瘦。","慢忆赋别东风，待新词谱遍，吴趋歌口。","后日西园，春好在，留得一双鹤守。","蓬海仙踪，蓟门归梦，叠鼓催津堠。","长安花发，故袍鸳缕能绣。"]},{"t":"三姝媚","f":"古风","c":["吴坊歌板地。","借青尊浇残，一春红泪。","有限柔魂，似海棠枝上，断丝还系。","第一轻盈，禁几度、沈郎腰细。","莫遣垂杨，空向高楼，替人眠起。","昨夜欢盟须记。","但醉粉迷香，枕边花气。","雨薄云轻，怕梦来都变，那时情味。","晓帐愁分，却又惜、黄昏容易。","自恁幽期能耐，而今倦矣。"]},{"t":"玉梅令","f":"古风","c":["纤云压臂。","双绾春魂细。","歌尘散，酒香红被。","算三分好月，尽向梦中园，一分是影，二分是泪。","醒来甚处，玉温花腻。","悤悤别，那人睡里。","怕相思一剪，断作水西流，更休劝，晓莺催起。"]},{"t":"蝶恋花 其一","f":"古风","c":["风雨西楼罗被共。","万缕情丝，谁补天衣缝。","花亸卧屏银扇动。","交枝还妒钗头凤。","和泪相留和泪送。","费尽啼红，一霎鸳盟重。","别枕愁来残酒中。","不如各自销春梦。"]},{"t":"蝶恋花 其二","f":"古风","c":["睡爱新凉妆爱澹。","花艳交扶，鸳锦文波展。","荷露兰风秋夜转。","一床红迹相思染。","醉枕金钏明玉腕。","细看香瘢，的的情深浅。","梦里早知魂易断。","年时悔向花前见。"]},{"t":"蝶恋花 其三","f":"古风","c":["园饮夜酣花悄悄。","四绕朱阑，影底提携到。","醉语欺花同一笑。","无端轻占伊怀抱。","莫惜佳期和梦杳。","啼破春痕，一觉窗鸦晓。","欢怨今年无计了。","安排蜡泪成灰早。"]},{"t":"蝶恋花 其四","f":"古风","c":["一叶秋阴辞露井。","暗卜星期，怕与西风近。","冰簟横陈双玉并。","镜波不警鸳鸯影。","却道连宵清睡损。","今夜如何，彻晓无眠肯。","未必凉魂疏宝枕。","起来犹自和衣寝。"]},{"t":"蝶恋花 其五","f":"古风","c":["唾月吹花都意满。","自理新娇，事事无拘检。","争拟欢游成美眷。","歌前妒煞閒莺燕。","声价因谁花里占。","浩态狂香，只较当时减。","相见朝朝还泪眼。","不应蕉萃还凝澹。"]},{"t":"蝶恋花 其六","f":"古风","c":["夜夜对花能几醉。","一掬兰情，枉解湘皋佩。","莫遣馀香销别袂。","去年今日犹初会。","断雨飘云谁点缀。","疏俊年华，珠玉词空费。","惆怅锦屏虚卧内。","酒醒细领春残味。"]},{"t":"惜红衣","f":"古风","c":["小榭微波，疏帘暗雨，夜凉横玉。","珍簟湘文，溶溶见新浴。","云衣卷尽，禁一搦、宫腰纤束。","春足。","红印枕绡，趁钗花轻拂。","馀欢梦续。","记否西园，兰盟共情酷。","当时醉语，欸曲伴花宿。","空把雨襟残泪，销与画屏银烛。","任月胧长满，终是素娥成独。"]},{"t":"花犯","f":"古风","c":["袅红情，欹风歌袖，花前去年见。","澹欢浓怨。","都误了、因循还待谁遣。","绣囊桂子香重荐。","新期空月满。","甚近日，病来疏酒，新凉人易倦。","秋宵漏长语迟迟，相携未有别，安排肠断。","鸳枕侧，惊呼起、泪花红泫。","殷勤问，旧盟玉镜，应悔向、卢家窥半面。","但暗记，几回栖并，输他梁上燕。"]},{"t":"解连环","f":"古风","c":["夜萤流碧。","隔冰绡替月，暗窥红隙。","恁几度、贪醉留欢，总不似那回，背镫初夕。","自误娇痴，甚恩怨，变歌成泣。","想移襟换抱，尽被泪花，染作胸臆。","相思坠红信息。","奈熏篝宿被，依旧狼藉。","最记忆、挽断罗衣，又催送花前，忍问踪迹。","一枕新凉，各睡去，更谁追惜。","绕云屏，翠峰十二，梦来自觅。"]},{"t":"浣溪纱","f":"七言古诗","c":["暗雨吹香小苑空。","落花捻尽不离红。","恨郎轻薄似东风。","旧著罗衣香未减，新熏绣被梦谁同。","莫因閒语阁欢踪。"]},{"t":"玉烛新 汛雨花步叩舷而歌","f":"古风","c":["秋香披酒袂。","正卧雨吴篷，镜天如醉。","珠镫暗坠。","空明影、散作流花轻碎。","亭台近水，荡不尽、伤高清泪。","残篴外、休倚黄昏，孤尊更呼谁对。","鸥边浪迹年年，叹客里风情，半销疏媚。","楚兰旧佩。","留恨事、付与满江歌吹。","题红惜翠。","甚近日、愁来无会。","空梦想、鸳侣双扶，依依自睡。"]},{"t":"三姝媚 题南湖菱唱图","f":"古风","c":["垂虹吟棹路。","问湖边鸳鸯，几时飞去。","怨绮愁罗，又闹红单舸，尽归前浦。","浅澹山妆，似瘦了、镜中眉妩。","怕向西风，采采歌来，暗闻清苦。","嫩碧浮根堪数。","想弱步微波，小蘋同赋。","满目飘零，渐晚香飞上，一楼烟雨。","坞篴村砧，相和处、秋声无主。","莫对画图空忆，南花自语。"]},{"t":"暗香 岁晚江空，微闻红儿消息，感忆白石垂虹载雪故事，和其二曲，寄声湖上。","f":"古风","c":["四桥柳色。","又曲波怨送，西泠残篴。","记傍玉楼，拂镜花枝手亲折。","无奈红销翠减，重题入、江郎閒笔。","回梦里、误了流莺，歌酒换离席。","倾国。","恨寂寂。","念去后枕函，泪粉还积。","凤弦代泣。","解诉飘零更谁忆。","惟有孀娥冷伴，曾印遍、吴天愁碧。","认载雪，湖上路、欲归未得。"]},{"t":"疏影","f":"古风","c":["吴篷载玉。","算石湖镜影，曾见鸳宿。","莫费新声，重换盈盈，伤春早倦丝竹。","相思更比梅花瘦，任月满，高楼西北。","想那时，授简题香，翠袖也怜清独。","休问风流旧地，马塍一径草，还似眉绿。","试唤歌前，几许吟魂，替了琵琶场屋。","多情只合江南老，却怨入、解红新曲。","待泪花、寄与东风，染遍画裙罗幅。"]},{"t":"法曲献仙音 和片玉词题漱药盦","f":"古风","c":["兰荐风疏，茜帷云密，好夜长将愁度。","抱月教歌，替花分泪，新成燕帘莺户。","正翠烛围香处，沉沉小楼雨。","醉时语。","算重逢，误伊憔悴。","佳约近，多病未应顿阻。","妆束澹风流，映山眉、还带愁妩。","解惜惺惺，托深情，空有豪素。","怕眉边梦老，又趁断肠人去。"]},{"t":"寿楼春 和梅溪赠夔笙同年","f":"古风","c":["寻西园年芳。","甚眉边旧月，还恋吟窗。","可忆题花吹泪，瘦来东阳。","凋旅鬓，催柔肠。","被燕莺、欺人清狂。","怕屧步销金，钩斜瘗玉，犹见故宫妆。","欢期短，离天长。","早词成楚怨，歌换吴腔。","那更凭高怀远，未春先伤。","空有梦、归何乡。","倦路迷，桃源渔郎。","但遗佩江皋，重逢莫忘兰芷香。"]},{"t":"苏幕遮 两裆","f":"古风","c":["碧纹圆，红晕皱。","一寸芳心，解护花前后。","忆著单绡初试酒。","玉臂酥瑩，交枕销魂骤。","掩双襟，怜半袖。","熨遍轻盈，细细相思扣。","恁使衣香和梦旧。","为贴冰肌，也占新来瘦。"]},{"t":"苏幕遮 帕腹","f":"古风","c":["剪霞单，兜月小。","豆蔻新梢，春染郎怀抱。","半幅罗云双玉罩。","吹蕊挼香，漏泄红情早。","臂纱宽，胸镜俏。","络索明珠，暗锁情丝老。","密密花房容粉爪。","叠作同心，解得连环少。"]},{"t":"解红","f":"古风","c":["移玉柱，尽金尊。","旧时红袖新啼痕。","长得人情似初见，月珑应不耐黄昏。"]},{"t":"浣溪纱","f":"七言古诗","c":["吴谚新传腊尽雷。","似闻羯鼓绕花回。","春槃明日荐缃梅。","南雪乍占檐鹊喜，北云争共渚云飞。","经年好计不成归。"]},{"t":"清平乐 新春赠别","f":"古风","c":["旧游连袂。","占了东风泪。","好事一年须计费。","酒半月初花未。","去年春在谁家。","断魂还是天涯。","休倚北楼高处，夜窗暗雨啼鸦。"]},{"t":"甘州 园夜看雪","f":"古风","c":["正玉梅荐酒，荡空香、飞水夜明楼。","爱吹镫暝坐，残熏冷幕，清啸谁酬。","梦里西园人去，斜月五湖舟。","满目飘零恨，不到沙鸥。","省是东风好计，做落花吹尽，还替花愁。","看林塘散影，春似镜中游。","记听歌，谢桥重倚，带荒寒高树乱鸦投。","苍云暗，故山归眼，天地悠悠。"]},{"t":"绛都春 夔笙新纳吴姬用梦窗为李筼房量珠贺韵赋此","f":"古风","c":["春衫旧线。","怅麝缕罢熏，西湖香远。","人似苧罗，新占东风吴王苑。","移花空惹流莺怨。","恁歌外，娇尘缭乱。","小屏轻帐，安排好近，玉梅庭院。","长见。","丝阑凤纸，背妆镜，暗写南花柔茜。","桃叶渡江，争共多情桃根换。","窥帘重记仙郎面。","正低户、三星夜转。","几回鹦语，教成绿窗睡暖。"]},{"t":"思远人 和小山词自题西崦浮家图","f":"古风","c":["柳桥阴阴寒食近，江上未归客。","閒花飞尽，东风轻信，年事怎销得。","画中烟岫空青滴。","洒澹醉时墨。","便著个五湖，采芝仙侣，一家好春色。"]},{"t":"忆旧游 壬辰寒食挈家游城东园","f":"古风","c":["认香阶屧印，宝鉴筝尘，无限春过。","坠梦玲珑影，怅风棂月幌，付与烟萝。","谢堂燕子重到，应识客来多。","渐暗柳吹绵，夭桃堕粉，那处闻歌。","销磨。","好时节，趁沼渌湔裙，芳霭清和。","漫拟蓬莱境，占全家仙步，近日凌波。","五湖更有佳约，移棹水云窝。","正霁宇舒眉，遥山不惜分黛螺。"]},{"t":"捣练子","f":"古风","c":["帘影静，粉香和。","澹澹妆眉细细歌。","今夜海棠花下酒，为谁风露得愁多。"]},{"t":"浣溪纱 其一","f":"七言古诗","c":["水色摇烟青漠漠。","清歌一片风前约。","残月马嘶闻晓角。","醉眠一夜同罗幕。","花好犹疑春梦恶。","堕枕钗声和泪阁。"]},{"t":"浣溪纱 其二","f":"七言古诗","c":["曙柳鸟啼未忍归。","露花烟叶共依依。","沉思昨梦已成非。","罢酒高楼人近别，绕船空水雁初飞。","几回相见更相违。"]},{"t":"芳草渡 叔由闻西风有怀归之曲，吴波容与，明月依人，感遇成歌，以当秋饯。","f":"古风","c":["倚醉遍，又梦趁吴篷，断魂重见。","指露桥归马，黄昏几度歌散。","临水珠玉感。","同天涯蓬转。","坠月悄，席上南花，一夜零乱。","堪念。","客亭帐饮，付与单衣销泪线。","漫追咏，皋兰秀句，西风送湘雁。","隔江篴语，正满目，山阳凄黯。","近别路，暗雨菰蒲自捲。"]},{"t":"齐天乐 西园感旧","f":"古风","c":["旧家池馆追凉地，伤心十年前后。","去燕空帘，疏萤小扇，难遣寻常时候。","阑干似旧。","算花下黄昏，几回垂手。","满院筝尘，翠阴门掩数行柳。","江南赋情最久。","俊游零落早，欢事稀有。","丝竹凋年，湖山费泪，销与西风词酒。","园居半亩。","笑双鹤栖依，占人清瘦。","见月登楼，过秋知健否。"]},{"t":"声声慢","f":"古风","c":["垂灯曲户，漏箭丁丁，临明一阵凉雨。","欲起还眠，好梦也愁重做。","朝朝泪珠洗面，待帕罗，替人分付。","怎点滴，到君心、占得几分清苦。","旧日钿车花路，携手地、依然断魂来去。","冷澹歌前，人似过秋纨素。","西阑又飘桂子，指幽期，月圆重误。","奈病里，恨恹恹、长是暗度。"]},{"t":"御街行","f":"古风","c":["新寒侧帽残萸坠。","又过登高会。","去年花下玉交卮，夜夜轻盈扶醉。","好风凉月，只今成恨，天亦多情悔。","翠峰十二高楼对。","梦与行云背。","飘镫狭路暗相期，销得几番蕉萃。","见诗无语，别后无泪，卧后还无寐。"]},{"t":"月下笛 雪中见池北横枝有忆和片玉","f":"古风","c":["纸帐吹魂，芦帘低额，小眉横碧。","微吟掩抑，月落高楼闻篴。","卧空寒、残雪自香，一枝未折春暗识。","似盈盈碎玉，红冰销碎，有情沾臆。","东风旧地，携素手重来，画阑空拍。","簪英荐酒，苦为金钗留客。","想西江、缟衣夜还，采珠作泪花下滴。","剪苍云，又听栖禽对语成叹息。"]},{"t":"虞美人 其一","f":"古风","c":["啼红一枕酬恩重。","暂见还疑梦。","销魂未抵梦中多，怊怅新来无梦、奈君何。","临分衣带留芗泽。","此恨谁晓得。","今年花满去年枝。","莫待明年憔悴、绿阴时。"]},{"t":"虞美人 其二","f":"古风","c":["佳期长比初三月。","意好无圆缺。","霜花抵死守阑东。","剩得春心一寸、可怜红。","玉钗头上花狼藉，堕地知谁惜。","新愁重理旧眉端。","著意人前妆澹、与郎看。"]},{"t":"鹧鸪天","f":"古风","c":["漫把新词当曲听。","尊前一例断肠声。","料应欠我伤春泪，抱著红绡过一生。","花可可，意盈盈。","小窗斜月旧帷屏。","天涯已自多情误，争忍才名更误卿。"]},{"t":"水调歌头","f":"古风","c":["春梦薄于酒，一醉已千秋。","为花起舞回雪，花下玉尊愁。","却笑髯仙多事，赢得人间香火，歌咏又苏州。","旧会几人在，残槁落沧洲。","弄腰篴，怀蜀客，被紫裘。","十年墨泪，题处双塔白云留。","欲唱大江东去，又恐琵琶拨断，风月不分忧。","待把寒梅荐，长啸上西楼。"]},{"t":"折红梅","f":"古风","c":["记西楼筝雁，曾迎素手，珠槃花乱。","甚东风、不管世情，红罗映雪先绽。","吹香枕畔。","凉玉浸、宫黄妆浅。","那回睡里、谁斗轻盈，奈鸾帕重题，泪粉相间。","华年美眷。","说仙处无双，画图传看。","殷勤把、一枝问讯，江南板桥红遍。","安排鸳桨，寻梦度、五湖春远。","怎便付与、雨洗烟梳，待流霞双举，见花须劝。"]},{"t":"暗香 余昔和石帚暗香疏影二曲为感西湖之别也，今冷红阁子落成经年，不可无词以报春，再赋梅枝，切情惆怅。","f":"古风","c":["画春一色。","更绕阑唤起，东风双篴。","漫下玉阶，不惜高枝为谁折。","长记西楼别宴，题红处、都成愁笔。","算此际、索笑重逢，花下月同席。","南国。","往事寂。","叹梦老石湖，乱雪香积。","翠禽暗泣。","曾见盈盈正长忆。","休倚横桥十四，低唱遍、烟波空碧。","似旧曲、人好在，最难再得。"]},{"t":"疏影 探梅西碛，夜泊虎山桥，烟月空寒，花香积水，续赓此曲，侍儿以铁铜箫和之。","f":"古风","c":["横阑倚玉。","爱汎春一舸，来伴花宿。","梦熟湖山，红袖相携，题名暗刻新竹。","东风尽日香吹鬓，漫问讯、枝南枝北。","仗翠眉、解惜年芳，不似旧游凄独。","还见冰娥照泪，夜明满地水，吟弄寒绿。","直把金尊，浇遍珍丛，怎抵衣香连屋。","步虚自向瑶台近，更按彻、紫箫清曲。","趁睡妆、露粉重研，写入小蛮笺幅。"]},{"t":"减字木兰花 石壁精舍还虎山桥舟中作","f":"古风","c":["琅玕十二。","刻遍小名红閒翠。","寄语春知。","为惜年年长笋枝。","细香妆面。","临水隔花时一见。","却羡山花。","得近钗鬟贴脸霞。"]},{"t":"减字木兰花 登临岩最高顶眺月","f":"古风","c":["琴台夜峭。","片石重惊香屧到。","云意留山。","学得西施旧黛鬟。","流花镜里，几度阑干能并倚。","明日横塘。","犹有词人载雪航。"]},{"t":"玉楼春","f":"七言律诗","c":["朝朝花下催梳掠。","镜槛呵香妆澹薄。","误伊春睡比花浓，暂梦不离山水乐。","横塘一夕和烟泊。","却望琴台天样隔。","半空塔影落西曛，犹见云端红袖著。"]},{"t":"点绛唇 邓尉山看花夜还","f":"古风","c":["雪岫低鬟，橹枝欹月晴波趁。","祠山风信。","莫便吹红阵。","香满归篷，夜市烧灯近。","残寒褪。","小阑花韵。","打叠春人困。"]},{"t":"山中春事以祠山风信为落梅时节 蝶恋花 蓟门晚春","f":"古风","c":["塞上柳条青未遍。","已作花飞，乱扑东风面。","一夜流萍随梦远。","江南春好肠应断。","谁道长安桃李艳。","黦地狂尘，春尽无花见。","日日朱门车马散。","夕阳空有巢林燕。"]},{"t":"杨柳枝 其一","f":"七言绝句","c":["头白巢林乌夜啼。","深闺罢织怨辽西。","东风陌上多离别，争拟长条系马蹄。"]},{"t":"虞美人 拟宫词春怨","f":"古风","c":["罗屏梦冷燕云绿。","山枕销香玉。","手挼裙带绕阶行。","肠断故宫残月五更莺。","桦烟钿毂嬉春夜。","往事空花谢。","杏梁双燕守长门。","犹似替人朝暮话君恩。"]},{"t":"河传","f":"古风","c":["池上。","镫幌。","海棠时。","疏绮香移步迟。","卷帘镜中花一枝。","相思。","素屏难画伊。","啼粉夜寒频梦见。","歌尘断。","头白空梁燕。","画檐铃。","连雨声。","五更。","水漂花出城。"]},{"t":"永遇乐 和稼轩北固亭怀古兼忆星海焦山","f":"古风","c":["江北江南，青山占尽，台观高处。","击楫狂吟，凭栏危眺，潮打孤城去。","吴头楚尾，此间天限，空有射鸥人住。","看残阳、蜗蛮一角，中兴气竞龙虎。","金焦入眼，楼船东下，销得英雄一顾。","白帝城边，有情乡水，应过夔门路。","昔年沉陆，战场荒草，换了酒旗戏鼓。","重阳近、茱萸旧会，故人健否。"]},{"t":"扬州慢甲午九月游广陵平山堂曲宴即席和白石韵","f":"古风","c":["十里春风，二分明月，杜郎旧熟游程。","甚江湖病眼，为路柳偏青。","正哀吹、连天警燧，故人重见，尊酒谭兵。","怅烟堤、鸦点残阳，空下台城。","后庭玉树，奈歌前、重听堪惊。","叹木落淮南，留人几处，丛桂多情。","我亦过江词客，山堂在，倦赋秋声。","念天涯归梦，明年芳草还生。"]},{"t":"后庭花 湖上草堂和孙光宪","f":"古风","c":["倦桡重问青芜国。","竹西秋色。","山好过江依旧绿。","一笑留得。","旧家池馆在，俊情谁识。","鬓丝如织。","十里珠帘成梦忆。","此意何极。"]},{"t":"醉落魄 山塘夜归记邻舟歌者和范石湖","f":"古风","c":["珠吭清绝。","别船酒散灯微灭。","回波荫翠交槐樾。","残梦高楼，篴里旧时月。","水香帘隙明肌雪。","轻风催漏铜龙咽。","镜中花好无人折。","明日歌尘，留与断红说。"]},{"t":"绛都春 溪堂卧雨，有巳秋愿夏之思，陈衡仲改此曲为平调，感音凄厉，因次韵于水西桂丛歌之","f":"古风","c":["残蝉送暑，近桂阴院落，轻暖轻寒。","病枕睡迟，垂灯疏绮雨声閒。","题红惯听吴桥水，翠眉曾损愁弯。","半襟秋粉，一屏冷麝，梦老丛兰。","几处登临泪眼，早花销酒力，草没诗痕。","十载倦游，霜簪吟鬓镜尘昏。","归期总为伤春误，故山应有啼鹃。","断魂犹系，西风咫尺画阑。"]},{"t":"鹧鸪天 冷红簃逭暑赋得侧艳小词以罗帕澹墨题之","f":"古风","c":["水榭移灯月到床。","花阴四捲茜纱凉。","兰汤竞夕宜温玉，帘外风来澡豆香。","肌雪净，脸波长。","枕函花隐玉清防。","自嫌澹素无梳洗，犹被池莲妒睡妆。"]},{"t":"乌夜啼","f":"古风","c":["八尺龙须方锦，几重凤尾香罗。","蕉云一枕新凉展，昨夜小窗多。","歌力最宜酒殢，睡香还比花和。","无端梦见年时事，红晕上梨涡。"]},{"t":"柳梢青","f":"古风","c":["鸳沼流红，莺栊落翠，舫馆清华。","咫尺回阑，几重花影，一角天涯。","怜伊半袖青纱。","尽拂遍、东风柳花。","欲寄相思，水香坊曲，艳雪人家。"]},{"t":"法曲献仙音 题语石道人填词图和石帚韵","f":"古风","c":["经乱湖山，送春池馆，日暮相逢何处。","墨泪单衣，白头行卷，沾愁共惜残俎。","怕故苑、沧波地，依前断魂去。","漫回顾。","早东风、制成乡泪，空夜夜、看剑引杯狂舞。","我醉听君歌，奈萧条、时事如许。","唾月推烟，更花閒，莫道俊句。","甚江关游勌，老向西园听雨。"]},{"t":"秋霁","f":"古风","c":["残雨空园，剩水佩风裳，暗写愁色。","未了琴尊，已凉亭馆，病馀感秋无力。","坠红信息。","废池何恨成凝碧。","怅故国。","千里。","暮云江上倦游客。","还念旧社，醉墨题襟，十年飘零，清事都寂。","晚香丛鸥，边梦续疏，狂花也笑头白。","一语问花应解得。","又断魂处，待赋卅六芳陂，载秋单舸，冷枫红驿。"]},{"t":"念奴娇 壶园自寿","f":"古风","c":["百年几醉，只壶中老我，天地无恙。","自见乘槎仙客去，愁满十洲烟痕。","沧海尘飞，故国秋澹，梦断拿云想。","江关词赋，倦怀自恁疏放。","一笑弄月婆娑，长松招鹤，凄厉千山响。","卧看青门销旧辙，世外樵风相况。","哀乐中年，登临残泪，付与玲珑唱。","西楼横竹，五湖对酒如掌。"]},{"t":"小重山 题碧湘馆水墨细竹","f":"古风","c":["寒玉琅琅湘绮明。","镜台霏缥粉、细香生。","露啼烟笑梦轻盈。","春风笔、空翠点罗屏。","斑碧泪纵横。","墨花浓染处、若为情。","江娥哀管倚云惊。","玲珑玉、裁作凤鸾声。"]},{"t":"翠楼吟 瓠庵北楼夜宴和白石韵","f":"古风","c":["海泪珠零，霜歌剑涩，边庭未报环赐。","鸥盟云水续，漫吟入江城哀吹。","西山摇时，念病眼离青，秋眉销翠。","吴娃丽。","篴中杨柳，断肠声细。","胜地。","瓠落能容，笑谢家棋墅，百年儿戏。","凉风归燕早，但残照乌衣邻里。","尊前愁味，有半壁诗尘，一楼花气。","横波外。","旧情还见，月棱新霁。"]},{"t":"青玉案","f":"古风","c":["吴波绿尽回肠路。","又送客桥西去。","晚色年芳长暗度。","水滨鸥榭，木棉莺户。","知是愁来处。","良游莫共伤春暮。","画壁犹歌旧时句。","蹋马花街红寸许。","绕阑呼酒，倚帘吹絮。","一曲潇湘雨。"]},{"t":"柳梢青","f":"古风","c":["帘雨樱桃，斗风芍药，砌雪荼蘼，为送春归。","小窗笺管，误了书期。","侬家罨画桥西。","占明月、前溪后溪。","长把团栾，镜中圆梦，空照花啼。"]},{"t":"柳梢青","f":"古风","c":["忆别西湾，茨菰碧烂，菡萏红乾。","恼见花时，荡丝十丈，不系郎船。","葳蕤绿扇长关。","甚明月、知人未眠。","秋烛新啼，春衫残睡，都到愁边。"]},{"t":"琵琶仙 江上早春感事别于晦岩","f":"古风","c":["头白渔郎，问重见、洞里桃花何世。","流水休恋桃源，蓬莱正尘起。","凝望眼、金扃玉阙，渐销尽、海东云气。","犯斗槎回，支机石老，题恨无地。","又还念、辽鹤归来，奈乡梦、重重渺难寄。","愁向十洲屏画，说沧桑馀事。","残篴外、西江落月，见故宫、洗面清泪。","谩倚烟柳津桥，杜鹃声里。"]},{"t":"虞美人 吴城长春巷，为明人王百谷故宅，有马湘兰画壁，今沦为荒墟，赋此记之","f":"古风","c":["断肠吴苑西桥水。","中有盈盈泪。","王昌何恨老墉东。","赢得素心人与画东风。","一时南院题香笔。","春去花留迹。","似伤故国沼成空。","犹有几枝红露泣珍丛。"]},{"t":"遐方怨","f":"古风","c":["金雀扇，玉蝉翘。","悔结同心，带围新来宽素腰。","宿妆山额睡黄销。","照花莺镜里，不成娇。"]},{"t":"水调歌头 中秋夜城西楼望月和东坡","f":"古风","c":["楼阁夜明水，枫冷雁横天。","不知今夕何夕，对此思华年。","记我骑云飞去，曾到广寒仙宇，天袂至今寒。","云外小垂手，声在步虚间。","罢歌舞，何处篴，又惊眠。","十洲三岛，在眼一镜万沤圆。","画鼓连江暝合，醉把铜壶敲缺，天际此身全。","帆影碧空尽，秋水自娟娟。"]},{"t":"疏帘澹月 见秋池落花有忆用张东泽自制谱","f":"古风","c":["三花两蕊。","渐散作秋文，细风行水，乱点鱼唼黯黯，冷香吹起。","微波似惜流芳意，聚桥阴、断钿如缀。","小澜虚縠，玉纤一掬，旧情红碎。","想江上、芙蓉月坠。","正露房弹粉，曲尘浮翠。","照影惊鸿，还见镜中铅泪。","西亭残梦销罗被，恋馀香依旧憔悴。","曲沟片叶，飘零恨晚，一般离思。"]},{"t":"章台月 吴姬宛宛，家在半塘桥，尝述其小时七夕遇仙事，感而赋此","f":"古风","c":["露槃花水。","蛛丝一缕秋魂细。","香囊暗度凌波地。","吹粉仙梯，随步乱红起。","清宵记曲西池醉，天衣香冷和云睡，月中小字明珠坠。","笙鹤相期，重解绮兰佩。"]},{"t":"汉宫春 题春波遗泽图","f":"古风","c":["水竹幽栖，认春波桥畔，旧隐松关。","清光一奁碎玉，还写虚澜。","兰纫芰制，想风襟、委迹高寒。","问仙里、知津几世，桃花流向人间。","一笑蓬莱清浅，任采芝人老，贯月槎还。","依依白云半舍，乱叶荒湾。","草堂好在，占斜阳、故国青山。","羡尘外、柴桑未远，满瓢诗挂渔竿。"]},{"t":"高阳台 为粟香室主人题冰泉集","f":"古风","c":["斗玉花田，题璚梅岭，清词绣遍蛮弓。","梦换萝衣，倦怀乌帽尘笼。","故山落尽荼蘼雪，怕燕归、还误东风。","谩销凝，暗草池尊，乱叶楼钟。","苍梧旧迹追遗赏，忆呼猿烟语，招鹤云踪。","一掬寒湫，采珠应叹江空。","袖中重见沧州槁，倩夜弦、弹泪鲛宫。","感年芳、红雨桄榔，碧月芙蓉。"]},{"t":"霜天晓角 枫桥夜泊","f":"古风","c":["风镫乱叶。","蛩响和愁叠。","直道千山飞雨，开帘见，满江月。","空澈。","帆影绝。","荻湾秋载雪。","鸥外一星渔火，红不到、画阑缺。"]},{"t":"八六子 琴台在灵岩最高顶，秋晚登望怀古，有辞舟客邓子石瞿扣舷而和之","f":"古风","c":["步幽遐。","屧廊黄叶，西风响出樵车。","叹断壁仓皇残霸，好山分付名娃，月明自斜。","秋容相对仓华。","眉黛依稀岫萼，髻鬟散作云花。","问鹿迹荒台，何年枯藓，马蹄片石，谁家芳草，空馀歌舞销尘故国，登临费泪天涯。","黯流霞。","飘零满溪旧纱。"]},{"t":"西江月 木渎舟中同石瞿分题赋灵岩古迹","f":"古风","c":["怊怅故宫花草，春风细步香迷。","翠沟愁入越来溪。","一箭五湖波起。","采采空闻流水，芳心早逐鸱夷。","漂花若到若耶西。","羞见浣纱邻里。"]},{"t":"西江月 浣花池","f":"古风","c":["寒绿一方秋净，年年无限流香。","菱花曾见洗残妆。","肠断千丝越网。","不信吴宫是沼，分明对此茫茫。","金烟珠粉总凄凉。","玉甃依然月样。"]},{"t":"菩萨蛮 石壁精舍望太湖诸山","f":"古风","c":["烟林星火渔扉静。","潮平沙觜知霜信。","红叶过湖船。","水明初雁天。","夜楼何处篴。","孤月飞空碧。","帆影欲浮山。","一峰云载还。"]},{"t":"菩萨蛮","f":"古风","c":["云容入暝山如睡。","雨馀扶起矾头翠。","残月落疏钟。","小楼霜气浓。","年时题醉地。","瘦石封菭字。","花影两愁鬟。","镜螺宜夜看。"]},{"t":"菩萨蛮 从玄墓山夜还虎山桥","f":"古风","c":["一湖风色明岩牖。","乱峰木落如人瘦。","笼烛引秋山。","满衣云叶寒。","隔崦呼月上。","归路闻樵唱。","林影水生烟。","桂花香到船。"]},{"t":"鹧鸪天 池梅疏萼点缀小春采香成咏","f":"古风","c":["黄叶围扉蔽竹窥。","江城花讯鹤先知。","旧时西崦初三月，此是东风第一枝。","横瘦影，弄愁漪。","芳程未较岭头迟。","镜中一幅伤春槁，和水和烟画与谁。"]},{"t":"琴调相思引 藕翘小榭听宛宛歌湘春夜月","f":"古风","c":["记曲香名月里传。","珠吭风约绕花圆。","暗抛歌豆，红破第三弦。","艳拍重商秋玉谱，新题细品瘦金笺。","井华清处，不数柳屯田。"]}]};